quests[39015] = { id = 39015, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brummer", sourceObjective = "<Der Welpe wedelt aufgeregt mit dem Schwanz, als er Euch erblickt. Er scheint sehr dankbar zu sein.>", sourceObjectiveStatus = "unverified-source-field" }
quests[39017] = { id = 39017, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rise to the Occasion" }
quests[39018] = { id = 39018, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Erzmagiers", description = "Erzmagier Khadgar möchte Euch um einen sehr dringenden Gefallen bitten. Er macht sich ernste Sorgen wegen zusätzlicher Gefahren, die diese Welt für Azeroth bereithalten mag. Er braucht Eure Unterstützung, um sich darum zu kümmern. Bitte sucht ihn in seinem Turm östlich von Talador im Sumpf von Zangarra auf.", sourceObjective = "Sprecht mit Erzmagier Khadgar bei Khadgars Turm in Zangarra.", sourceObjectiveStatus = "unverified-source-field" }
quests[39019] = { id = 39019, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Erzmagiers", description = "Erzmagier Khadgar hat den nächsten Schritt im Kampf gegen den Schattenrat festgelegt. Bitte sucht ihn in seinem Turm östlich von Talador im Sumpf von Zangarra auf.", sourceObjective = "Sprecht mit Erzmagier Khadgar bei Khadgars Turm in Zangarra.", sourceObjectiveStatus = "unverified-source-field" }
quests[39020] = { id = 39020, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein brennender Pfad durch die Zeit", description = "Der gleißende Stern wirft sein Licht auf das Land und lässt die Erde verdorren und ganze Landschaften versengen. Es ist ein gnadenloser, fast schon bösartiger Stern. Unter seinem Einfluss eröffnen sich neue Wege – zu weit entfernten Orten und sogar zu weit entfernten Zeiten. Kein Weiser ist in der Lage, die Bedeutung dieses Zeichens vollständig zu verstehen, aber das Glück ist mit den Mutigen.", sourceObjective = "Schließt 5 Zeitwanderungsdungeons ab.", completion = "Ah, {name}. Ihr seid zurück. Euch umgibt wahrlich eine Aura aus einer anderen Welt.", sourceObjectiveStatus = "unverified-source-field" }
quests[39021] = { id = 39021, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein gefrorener Weg durch die Zeit", description = "Der kalte Stern wirft sein frostiges Licht auf das Land und selbst die Schatten ziehen sich zurück. Es ist ein Stern wie kein zweiter, der alle Wärme und Leben entzieht. Unter seinem Einfluss eröffnen sich neue Wege – zu weit entfernten Orten und sogar zu weit entfernten Zeiten. Kein Weiser ist in der Lage, die Bedeutung dieses Zeichens vollständig zu verstehen, aber das Glück ist mit den Mutigen.", sourceObjective = "Schließt 5 Zeitwanderungsdungeons ab.", completion = "Ah, {name}. Ihr seid zurück. Euch umgibt wahrlich eine Aura aus einer anderen Welt.", sourceObjectiveStatus = "unverified-source-field" }
quests[39022] = { id = 39022, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Erzmagiers", description = "Erzmagier Khadgar hat den nächsten Schritt im Kampf gegen den Schattenrat festgelegt. Bitte sucht ihn in seinem Turm östlich von Talador im Sumpf von Zangarra auf.", sourceObjective = "Sprecht mit Erzmagier Khadgar bei Khadgars Turm in Zangarra.", sourceObjectiveStatus = "unverified-source-field" }
quests[39023] = { id = 39023, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Erzmagiers", description = "Erzmagier Khadgar hat den nächsten Schritt im Kampf gegen den Schattenrat festgelegt. Bitte sucht ihn in seinem Turm östlich von Talador im Sumpf von Zangarra auf.\n\nDies wird nicht lange dauern.", sourceObjective = "Sprecht mit Erzmagier Khadgar bei Khadgars Turm in Zangarra.", sourceObjectiveStatus = "unverified-source-field" }
quests[39024] = { id = 39024, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Erzmagiers", description = "Erzmagier Khadgar hat den nächsten Schritt im Kampf gegen den Schattenrat festgelegt. Bitte sucht ihn in seinem Turm östlich von Talador im Sumpf von Zangarra auf.\n\nDies wird nicht lange dauern.", sourceObjective = "Sprecht mit Erzmagier Khadgar bei Khadgars Turm in Zangarra.", sourceObjectiveStatus = "unverified-source-field" }
quests[39025] = { id = 39025, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Umklammerung des Unterkönigs", description = "Wenn es an dieser ganzen Situation ein Gutes gibt, dann ist es die Tatsache, dass Dargrul nicht weiß, wie man den Hammer benutzt.\n\nEr glaubt immer noch, dass der Hammer eine Waffe ist und kein Werkzeug der Schöpfung.\n\nDennoch hat er unsere Stammesmitglieder in Fäusten aus Stein festgesetzt, die er aus der Erde beschworen hat. Unsere Waffen haben sich gegen diese Magie als nutzlos erwiesen.\n\nIhr verfügt womöglich über genug Macht, um diese Fäuste aufzubrechen. Könnt Ihr uns helfen?", sourceObjective = "Rettet Jale Flussmähne, Kriegerheld Oro und Oakin Eisenstier.", completion = "Es muss ein ganzes Zeitalter her sein, dass sich die Drogbar in so großer Zahl an die Oberfläche gewagt haben.\n\nSie wurden zu den finsteren Märchen, die wir den Kindern erzählen.", sourceObjectiveStatus = "unverified-source-field" }
quests[39026] = { id = 39026, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Drogbar", description = "Es reichte Dargrul nicht, dieses Dorf zu zerstören. Er hat obendrein seine Steinräuber entsandt, um alles an sich zu reißen, was übrig ist.\n\nBitte, Champion, beweist meinem Volk, dass Ihr der Held seid, den ich in meinen Visionen gesehen habe.\n\nTötet so viele Steinräuber, dass ihre Entschlossenheit schwindet.", sourceObjective = "Tötet 8 Drogbar bei der Flusswindung.", completion = "Eure Kampffähigkeiten sind beeindruckend.", sourceObjectiveStatus = "unverified-source-field" }
quests[39027] = { id = 39027, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dargrul und der Hammer", description = "Wir wollen gerade einen Drogbar in eine Höhle verfolgen, dabei haben wir das unseren Kindern immer verboten.\n\nAllerdings sind einige unserer Kriegerhelden bereits Dargrul dort hinein gefolgt.\n\nKommt, schließt Euch uns im Kampf an, damit wir den Hammer von Khaz'goroth zurückerobern können.", sourceObjective = "Stellt Euch Dargrul dem Unterkönig.", progress = "Dies ist ein harter Tag.", completion = "Oro und die anderen? Haben auch sie es zurückgeschafft?\n\nWas für ein Gemetzel. Heute sind so viele Kriegerhelden gefallen.\n\nEines ist nun klar geworden: Wir werden die vereinte Kraft der Hochbergstämme brauchen, wenn wir den Hammer zurückholen wollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[39029] = { id = 39029, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidigung des Tempels" }
quests[39030] = { id = 39030, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arauk Nashal 70:JP3 - Aggramar's Vault - Tracking Quest Cleared - God-King Intro" }
quests[39031] = { id = 39031, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Ivory Sentinel" }
quests[39032] = { id = 39032, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Treffen mit Saylanna", description = "Waldgeister waren schon immer boshafte Kreaturen, aber in letzter Zeit ist ihre Bosheit in Gewalt umgeschlagen.\n\nEine von mir sehr geschätzte Druidin, Saylanna Flussbrise, hat mir berichtet, dass sie die Nistgründe der Feendrachen angreifen.\n\nDer Mondschwingentümpel befindet sich südlich von hier. Dort findet Ihr auch Saylanna.", sourceObjective = "Sucht Saylanna Flussbrise am Mondschwingentümpel auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[39033] = { id = 39033, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeit zum Angriff", description = "Diese Sternenkonstellation ruft ungewöhnliche Vibrationen in den über ganz Draenor verstreuten Kristallen, den Relikten der uralten Apexis, hervor. Einige schwören, dass diese Kristalle sich vermehren, wenn man sie sich selbst überlassen unter den Nachthimmel legt. Aber noch nie konnte jemand dieses Phänomen mit eigenen Augen beobachten. Aber was auch immer der Grund sein möge, jetzt ist die beste Zeit, nach diesen Kristallen zu suchen.", sourceObjective = "Schließt 5 Ziele in Apexisgebieten ab.", completion = "Gut gemacht, {name}. Glücklicherweise kann ein geübter Rutengänger mit Hilfe dieser Apexiskristalle unterirdische Ölvorkommen finden. Ich kann Euch diese Kunst leider nicht beibringen, aber Ihr könnt trotzdem von den Vorteilen profitieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[39034] = { id = 39034, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abgesandter des Krieges", description = "Wenn das Zeichen des Gesandten am Nachthimmel leuchtet, festigen die Sterne ihre bestehenden Bande und knüpfen neue. Freundschaft wird nicht leichtfertig vergeben und nur durch Taten wird Treue bewiesen, aber Vertrauen stellt sich in diesen Tagen schneller ein. Begebt Euch tief in die Höhlen und Festungen, um Euch als würdig zu erweisen.", sourceObjective = "Schließt 4 Dungeons auf dem Schwierigkeitsgrad 'Mythisch' ab.", completion = "Eure neuen Verbündeten haben Euch dies hier hinterlassen, um Euch für Eure Mühen zu ehren.", sourceObjectiveStatus = "unverified-source-field" }
quests[39035] = { id = 39035, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking: Horde Siegebreaker" }
quests[39036] = { id = 39036, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking: Alliance Siegebreaker" }
quests[39037] = { id = 39037, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking: Iron Horde Siegebreaker" }
quests[39038] = { id = 39038, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking: Resource Rich" }
quests[39040] = { id = 39040, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Aufruf zur Schlacht", description = "Das Sternbild des Kriegsherren beherrscht den Himmel und bringt allen Strategen Glück. Einige sagen, dieses Sternbild schärft die Instinkte von Kommandanten so weit, dass es Wahrsagerei gleicht. Wenn Ihr je daran gedacht habt, Euch auf dem Schlachtfeld zu beweisen, ist jetzt die richtige Zeit dafür.", sourceObjective = "Gewinnt 4 Schlachtfeldpartien.", sourceObjectiveStatus = "unverified-source-field" }
quests[39041] = { id = 39041, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Arena ruft", description = "Diese Sternenkonstellation ist ein düsteres Omen. Sie ruft Blutlust hervor und zwingt Krieger zur Teilnahme an tödlichen Nahkämpfen. Die Arenameister verdienen gut dieser Tage. Vermutlich wissen sie nicht einmal, warum so viele Krieger in ihren Arenen antreten wollen. Neben der fiebrigen Spannung erwarten alle, die mutig oder töricht genug sind, sich diesen Arenakämpfen zu stellen, große Belohnungen...", sourceObjective = "Gewinnt 10 Arenageplänkel.", completion = "Der Wind flüstert Euren Namen und gibt Kunde von Euren Siegen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[39042] = { id = 39042, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haustierchampion", description = "Dies ist eine wahrhaft ungewöhnliche Sternenkonstellation. Sie ist dafür verantwortlich, dass die kleinsten Kreaturen ungewöhnliche Fähigkeiten entwickeln. Keiner unserer Weisen kann dieses Phänomen erklären, aber für geschickte Zähmer ist dies eine perfekte Gelegenheit, ihre Fähigkeiten gegen andere auf die Probe zu stellen.", sourceObjective = "Besiegt 5 Spieler über 'Kampf finden' mit einer Gruppe aus Haustieren auf Stufe 25.", sourceObjectiveStatus = "unverified-source-field" }
quests[39043] = { id = 39043, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Beißsteinenklave", description = "Dies ist eine alte Drogbarenklave, mit der wir früher Handel getrieben haben. Jetzt ist sie eine Operationsbasis für ihre Raubzüge.\n\nIch brauche mehr Zeit, um die verbleibenden Kriegerhelden zusammenzurufen. Geht in die Enklave hinein und tötet alle, die Ihr dort vorfindet.\n\nVerschafft uns die Zeit, die wir benötigen, um unsere Kraft zu sammeln.", sourceObjective = "Tötet Beißsteindrogbar in der Beißsteinenklave.", progress = "Der Hochberg wird nicht fallen!", completion = "Danke, dass Ihr uns den Weg geebnet habt. Jetzt werden wir Dargrul direkt ins Visier nehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[39044] = { id = 39044, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ungenutzt" }
quests[39045] = { id = 39045, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Zoug" }
quests[39046] = { id = 39046, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Harbormaster Korak" }
quests[39047] = { id = 39047, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf der Illidari", description = "{name}, Altruis möchte Euch sofort an Krasus' Landeplatz sprechen.\n\n<Kor'vas beugt sich zu Euch und flüstert eindringlich.>\n\nIhr müsst Euch beeilen. Die Legion hat ihre Augen überall.", sourceObjective = "Sprecht mit Altruis dem Leidenden an Krasus' Landeplatz.", completion = "Wir müssen rasch handeln. Mit jeder Minute, die wir hier herumsitzen, gewinnt die Legion an Stärke.", sourceObjectiveStatus = "unverified-source-field" }
quests[39048] = { id = 39048, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Demolitionist" }
quests[39049] = { id = 39049, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Augen auf das Ziel", description = "Dieser Dämon hat sich als gänzlich nutzlos erwiesen. Ich habe die Seelensense eingesetzt, doch bisher hat er sich meinem Verhör widersetzt. Wir werden sehen, wie lang er das durchhält.\n\nIch habe eine andere Idee...\n\nNicht weit vor uns ist ein anderer Inquisitor. Diese Dämonen sind verheerende Teufelswirker, die durch schwebende Augen sehen und dunkle Pakte schließen. Wenn Ihr Euch seine Macht aneignet, könnte Jace Düsterweber sie in seinem Ritual einsetzen, um die Legion auszuspionieren.\n\nEr wird sie nicht kampflos aufgeben, also entreißt sie seinen kalten, toten Klauen.", sourceObjective = "Tötet Inquisitor Seelenschmerz und beansprucht seine Macht.", completion = "Die Essenz eines Inquisitors, ausgezeichnet. Allari hatte recht.\n\nAlso dann, beenden wir mein Ritual und sehen wir, was die Anführer der Legion im Schilde führen.", sourceObjectiveStatus = "unverified-source-field" }
quests[39050] = { id = 39050, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treffen mit der Königin", description = "Wir können einen Teil der Essenz verwenden, um mein Ritual zu beenden. Dann werdet Ihr die Anführer der Legion ausspionieren und ihre Pläne sehen können.\n\nBenutzt den Nethertiegel, um das Ritual abzuschließen.", sourceObjective = "Schließt das Ritual ab und spioniert die Anführer der Legion aus.", completion = "Das ist neu... Sie sieht wie eine Art Spinnendämon aus. Als ob die Legion auch noch Spinnen gebraucht hätte...", sourceObjectiveStatus = "unverified-source-field" }
quests[39051] = { id = 39051, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Um jeden Preis", description = "Wir müssen herausfinden, wo sich Varedis verkrochen hat. Und dazu müssen wir in dieses Gefängnis eindringen.\n\nTut einfach alles, was dazu notwendig ist.", sourceObjective = "Verschafft Euch Zutritt zur Violetten Festung und verhört Taldath den Zerstörer, um den Aufenthaltsort des Verräters Varedis zu erfahren.", progress = "Eine wirklich beeindruckende Vorstellung.", completion = "Suramar ist nicht weit von hier.", sourceObjectiveStatus = "unverified-source-field" }
quests[39054] = { id = 39054, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schiffsbau", description = "Das Erste, was wir für den Bau von Schiffen benötigen, sind Baupläne. Dank Eurer Hilfe konnte ich ein paar der besten aus den Eisendocks an mich nehmen, bevor wir dort ausgebrochen sind.\n\nAber wir müssen sicherstellen, dass diese Pläne nicht erneut in die Hände der Eisernen Horde fallen. Ich möchte, dass Ihr Euch diese Baupläne einprägt und sie dann vernichtet. Sagt mir einfach Bescheid, wenn Ihr das erledigt habt.", sourceObjective = "Merkt Euch die Baupläne und vernichtet die Beweise.", progress = "Habt Ihr Euch schon die Baupläne gemerkt?", completion = "Ha! Aus Euch machen wir schon noch einen echten Seebären! Dann wollen wir mal unser erstes Schiff bauen!", sourceObjectiveStatus = "unverified-source-field" }
quests[39055] = { id = 39055, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schiff im Griff", description = "Jetzt, wo wir die Pläne haben, sollten wir unser erstes Schiff bauen – ein Transportschiff! Sprecht mich an, wenn Ihr bereit seid, den Bau in Angriff zu nehmen.", sourceObjective = "Sprecht mit Yanas, um mit dem Bau eines Transportschiffes zu beginnen. Fügt es Eurer Schiffssammlung hinzu, sobald es fertiggestellt ist.", progress = "Hat der Schiffsbau schon begonnen?", completion = "Wir haben unser erstes Schiff! Gute Arbeit, {name}. Ich werde es gleich für die erste Reise nach Tanaan vorbereiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[39056] = { id = 39056, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flottenkommandant", description = "Wir sind in sehr kurzer Zeit sehr gut vorangekommen mit dieser Schiffswerft, {name}. Jetzt ist es Zeit für unsere erste Marinemission und die Eroberung der Meere von Draenor!\n\nIch werde einen hohen Aussichtspunkt einrichten müssen, um unsere Vorhaben auf See zu planen. Trefft mich nahe des Eingangs zur Schiffswerft, damit wir anfangen können.", sourceObjective = "Findet Merreck Fender in Eurer Werft und schließt eine Marinemission ab.", progress = "Habt Ihr schon eine Marinemission abgeschlossen?", completion = "Gute Arbeit, Kommandant! Eines Tages wird aus Euch ein ausgezeichneter Kapitän.", sourceObjectiveStatus = "unverified-source-field" }
quests[39057] = { id = 39057, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hoheit auf See", description = "Gul'dan hat keine Zeit dabei verloren, seine Diener des Schattenrates in jeden Aspekt der Befehlsstruktur der Eisernen Horde einzusetzen. Die Seeflotte, die einst nur Grommash loyal ergeben war, steht jetzt unter seinem Befehl. Wenn wir zurückschlagen wollen, brauchen wir mehr als nur ein paar Transportschiffe. Wir müssen ein Arsenal bauen.\n\nEuer Können wird benötigt, Kommandant. Baut Eure Werft aus und erschafft eine Flotte, die den Ozean erobern kann!", sourceObjective = "Wertet Eure Werft auf Stufe 2 auf.", completion = "Sehr gut, {name}. In diesen Docks herrscht reges Treiben.\n\n\n\nZeit, uns unbeliebt zu machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[39058] = { id = 39058, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geschöpfe von Draenor", description = "Ich bin immer auf der Suche nach neuen Haustieren für meine Sammlung und hier in Draenor habe ich schon einige ungewöhnliche Haustiere ergattert. Was haltet Ihr von einem Haustierkampf? Wenn Ihr mein bescheidenes Team besiegt, lernen wir beide vielleicht ein paar neue Tricks.", sourceObjective = "Besiegt Erris die Sammlerin in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[39059] = { id = 39059, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bansheefangen leicht gemacht", description = "Der komisch redende Vrykul hat mir gesagt, dass ich Euch hier treffen könnte. Ich habe Befehle von Graumähne. Anscheinend hat er Hinweise auf den Aufenthaltsort von Sylvanas!\n\nEr hat ein Lager am Fuße des Berges aufgeschlagen. Allerdings hat es Probleme gegeben. Offensichtlich rückt die Horde auf unsere Position vor.\n\nWir könnten Eure Hilfe brauchen. Ihr könnt ruhig meinen Greifen nehmen. Sagt mir einfach Bescheid, wenn Ihr zum Aufbruch bereit seid.", sourceObjective = "Sprecht mit Genn Graumähne in der Grauen Wacht.", completion = "Gut, dass Ihr den Weg hierher gefunden habt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[39060] = { id = 39060, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Müllverbrennung", description = "Es stimmt, dass wir vielleicht Hinweise auf Sylvanas' Aufenthaltsort haben. Ich kann es eigentlich kaum erwarten, dass mir die Bansheekönigin in die Hände fällt, aber die Situation hier an der Grauen Wacht erfordert sofortige Aufmerksamkeit.\n\nGestern informierte uns ein Regiment Wachen über Truppen der Verlassenen im Wald. Einige zeigten Symptome einer Seuche, die dem ähnelte, was wir schon in Gilneas erlebt haben. Die Verlassenen wollen so anscheinend die Graue Wacht verseuchen.\n\nSpürt ihre Vorratslager auf und vernichtet sie, bevor uns die Seuche überrennen kann!", sourceObjective = "Verbrennt die Seuchenvorräte der Verlassenen in der Nähe der Grauen Wacht.", completion = "Damit wäre diese Aufgabe erledigt. \n\nIhr habt den {race} der Grauen Wacht einen großen Dienst erwiesen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[39061] = { id = 39061, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flüstern aus der Dunkelheit", description = "Wir wissen weiterhin kaum etwas über die Aktivitäten der Horde in dieser Gegend. Aber ich hoffe, dass Ihr etwas daran ändern könnt.\n\nIn letzter Zeit wimmelt es in den Wäldern nur so von Sylvanas' Agenten. Die wenigen, die wir ausschalten konnten, trugen Befehle der Dunklen Waldläufer bei sich. Es ist offensichtlich, dass sie hier das Kommando führen.\n\nAchtet bei Eurer Jagd auf diese Aufklärungsbefehle. Durch sie könnten wir von Sylvanas' Plänen für diese Gegend erfahren.", sourceObjective = "Sammelt die Aufklärungsbefehle der Verlassenen von den Pirschern und Seuchenbringern der Schreckensreiter in der Nähe der Grauen Wacht ein.", progress = "Was habt Ihr gefunden?", completion = "Ausgezeichnet. So langsam können wir das Puzzle zusammensetzen.\n\nWir wissen vielleicht nicht, was Sylvanas' Truppen hier vorhaben, aber zumindest wissen wir, wo sie sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[39062] = { id = 39062, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Skold-Ashil", description = "Jetzt haben wir sie! Laut unseren Berichten suchen Sylvanas' Truppen nach irgendetwas in Skold-Ashil... einer Vrykulstadt nicht weit von hier. Wir müssen dort hin und sie aufspüren.\n\nIch hatte bereits Kommandantin Lorna Crowley und eine Einheit der Gilneasbrigade entsandt, um diese Position auszukundschaften. Trefft Euch dort mit ihr und findet heraus, wonach Sylvanas sucht.\n\nIn der Zwischenzeit werde ich die Flotte sammeln, um ihren Außenposten anzugreifen. Erst wenn ich ihr Lager in Schutt und Asche gelegt habe, ist der Gerechtigkeit Genüge getan!", sourceObjective = "Trefft Euch mit Kommandantin Lorna Crowley in Crowleys Spähposten.", completion = "Dann ist die Kavallerie also da?\n\nSehr gut. Wir müssen uns beeilen, wenn wir Sylvanas' Plan aufdecken wollen, bevor sie ihn umsetzen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[39063] = { id = 39063, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schildgeheimnisse", description = "Es ist mittlerweile offensichtlich, dass die Horde irgendetwas in Skold-Ashil vorhat. Leider wissen wir immer noch nicht, was sie im Schilde führen.\n\nWir glauben, dass es mit den Schildmaiden hier zu tun hat. Deswegen müssen wir mehr über sie herausfinden. Laut früherer Berichte der Späher versehen sie ihre Schilde mit Bildern, die ihre Geschichte darstellen.\n\nBegebt Euch in die Stadt und versucht, so viele Schilde wie möglich zu finden. Mit ein bisschen Glück finden wir heraus, was Sylvanas sucht.", sourceObjective = "Untersucht 6 gravierte Vrykulschilde in Skold-Ashil.", completion = "Val'kyr, sagt Ihr? Das ist schlimmer, als ich vermutet habe. Wenn Sylvanas in der Lage ist, weitere Val'kyr zu erschaffen, wird die Größe ihrer Armee grenzenlos sein!\n\nSie scheint es auf die Kammer abgesehen zu haben. Wir müssen sie aufhalten!", sourceObjectiveStatus = "unverified-source-field" }
quests[39067] = { id = 39067, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufrüsten der Flotte", description = "Ihr habt gute Arbeit da draußen geleistet, Kommandant. Wir benötigen allerdings noch mehr Erfahrung und Ressourcen, um diese Schiffswerft weiter aufzurüsten. Wenn wir unsere Ziele erreicht haben, können wir die Kapazität der Schiffswerft erhöhen!", sourceObjective = "Sammelt 1.000 Garnisonsressourcen, 1.000 Gold und schließt 15 Marinemissionen ab.", progress = "Schon Erfolg mit diesen neuen Marinemissionen gehabt?", completion = "Großartige Arbeit! Wir werden gleich mit der Arbeit an der Erweiterung beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[39068] = { id = 39068, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorherrschaft auf hoher See", description = "Unsere Vorherrschaft auf hoher See besteht fort!\n\nWir benötigen allerdings noch mehr Erfahrung und Ressourcen, um diese Schiffswerft weiter aufzurüsten. Wenn wir unsere Ziele erreicht haben, können wir die Kapazität der Schiffswerft noch weiter erhöhen!", sourceObjective = "Sammelt 2.500 Garnisonsressourcen, 2.500 Gold und schließt 25 Marineschatzmissionen ab.", progress = "Habt Ihr schon die Ressourcen gesammelt? Ich bin bereit, mit der Erweiterung zu beginnen!", completion = "Die Kontrolle über die Meere von Draenor ist in greifbarer Nähe!", sourceObjectiveStatus = "unverified-source-field" }
quests[39069] = { id = 39069, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Val'sharah - Treasure 024 - Moonclaw Vale - twh" }
