quests[39081] = { id = 39081, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Val'sharah - Treasure 033 - Bradensbrook - twh" }
quests[39082] = { id = 39082, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An die Arbeit", description = "Jetzt, wo wir eine Werft haben, müssen wir uns an die Arbeit machen und Schiffe bauen! Solog ist schon zu den Trockendocks gegangen. Wollt Ihr ihn nicht dort aufsuchen? Er sagte, er habe einen Plan.", sourceObjective = "Trefft Euch mit Solog am Trockendock.", completion = "Ich liebe den Geruch von frisch gefälltem Holz und Teer! Seid Ihr bereit, mit dem Bau zu beginnen?", sourceObjectiveStatus = "unverified-source-field" }
