quests[39090] = { id = 39090, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tötet sie alle!", description = "Findet sie, jagt sie, tötet sie. Erteilt unseren Feinden eine Lektion, die sie niemals vergessen werden.", sourceObjective = "Tötet 200 gegnerische Spielercharaktere.", sourceObjectiveStatus = "unverified-source-field" }
quests[39092] = { id = 39092, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aszendentenriten", description = "Unsere nächsten Schritte sind klar. Wir müssen in die Kammer eindringen und verhindern, dass Sylvanas die Macht erlangt, weitere Val'kyr zu erschaffen. \n\nDer Eingang ist versperrt und hat bis jetzt auch sie davon abgehalten, dort einzudringen. Aber Ihr habt vielleicht den Schlüssel zu dieser Barriere bereits entdeckt.\n\nIhr müsst <der nächste Aszendent/die nächste Aszendentin> werden.\n\nVollzieht die auf den Schilden dargestellten Riten und schaltet die Barriere vor der Kammer aus. Ich werde Graumähne von unseren Ergebnissen berichten. Er wird am Kampf gegen Sylvanas teilnehmen wollen.", sourceObjective = "Versucht, den Segen an den vier Schreinen im Tempel von Skold-Ashil zu erlangen und dann mit der Statue zu kommunizieren.", completion = "Schön, dass Ihr da seid, {name}.\n\nDer Angriff auf das Schreckensflutufer ist nicht gut gelaufen, und ich dachte schon, dass alles verloren sei, bis Crowley von Eurem Erfolg erzählt hat.\n\nUnd jetzt lasst uns diese Sache hier zu Ende bringen!", sourceObjectiveStatus = "unverified-source-field" }
quests[39093] = { id = 39093, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Val'sharah - River - Small Treasure 041 - ZTO" }
