quests[39107] = { id = 39107, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch fettere Beute", description = "Diese Schergen in Tanaan haben alle möglichen wertvoll'n Schätze. Ist noch immer schwierig, aber ich kann Euch jetzt viel mehr geb'n!", sourceObjective = "Beschafft schäbige Eisenmünzen für Gaunah.", progress = "Also habt Ihr alle erwischt?", completion = "Hey, habt sie ja alle! Wie wundervoll für uns beide. So viel kann ich Euch geb'n...", sourceObjectiveStatus = "unverified-source-field" }
quests[39108] = { id = 39108, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Val'sharah - Ash'theran - Medium Treasure 054 - twh" }
