quests[39117] = { id = 39117, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es hat sich ausgekrächzt!", description = "Papa hat dieses Dorf geliebt. Er wollte nie von hier fortgehen, nicht einmal in diesen schlimmen Zeiten.\n\nBevor er starb, sagte er mir, was ihn angegriffen hat: ein monströser Falke namens Rottschnabel.\n\nIhr kämpft doch gegen diese Untoten, oder? Würdet Ihr meinen Vater rächen? Wenn ja, dann findet Ihr die Bestie nordwestlich von hier. Sie fliegt entlang unserer Westroute zum Meer auf und ab.", sourceObjective = "Findet Rottschnabel am Bradenbach und schlagt der Bestie den Kopf ab.", progress = "Papa sagte immer, er würde diesen Ort nur auf einer Bahre verlassen.\n\nIch wünschte, er hätte nicht recht behalten.", completion = "Danke schön. Das ist ganz schön grausig, was? Ich glaube, ich hänge den über der Tür auf.\n\nUnd den hier könnt Ihr auch haben. Frisch gefangener Mooskiemenbarsch war Papas Lieblingsfisch.", sourceObjectiveStatus = "unverified-source-field" }
quests[39118] = { id = 39118, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lower Citadel Speed Tracking" }
quests[39119] = { id = 39119, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf Skold-Ashil" }
quests[39120] = { id = 39120, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Shield Forger" }
quests[39121] = { id = 39121, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Haunted Manor" }
quests[39122] = { id = 39122, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ende des Neuanfangs", description = "Die Bansheekönigin ist hier! Diese verderbten Pfeile erkenne ich überall wieder.\n\nDas ist der Moment, für den wir gekämpft haben. Sylvanas wird sich jetzt für ihre Verbrechen gegen Varian Wrynn und die Allianz verantworten müssen!\n\nAn die Waffen!", sourceObjective = "Stellt Sylvanas in der Kammer von Eyir.", completion = "Ihr seid wach! Wir hätten Euch fast verloren...\n\nNur gut, dass wir Euch und Graumähne rechtzeitig rausbringen konnten. Ansonsten hätten wir nicht den Effekt von Sylvanas' Gift rückgängig machen können. Es ist eine Schande, dass sie entkommen ist, aber ihre Pläne in Skold-Ashil sind gescheitert, und dafür gebührt Euch Dank. \n\nIch bin mir sicher, dass Graumähne eine Belobigung aussprechen wird, sobald er sich erholt hat. Ihr habt hier Großes geleistet, {name}.\n\nGilneas steht in Eurer Schuld.", sourceObjectiveStatus = "unverified-source-field" }
quests[39123] = { id = 39123, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Löwenpirsch", description = "Die Hügel sind voller Löwen, die ihre Beute aus der Ferne verfolgen. Die Großkatzen springen alles an, was ihnen ins Auge fällt. <Ein/Eine:r> {race} wie Ihr bildet da keine Ausnahme.\n\nDie meisten würden solch einem furchterregenden Raubtier zum Opfer fallen, aber aus meiner Jagdgesellschaft würde jeder mit diesen Biestern fertigwerden.\n\nBeweist, dass Ihr auch das Zeug dazu habt, indem Ihr einige dieser Pirscher zur Strecke bringt.", sourceObjective = "Jagt Kieferfelspirscher und -streuner im Kieferfelsbecken.", completion = "Ich sehe nicht einen Kratzer an Euch. Ich wette, die Löwen haben Euch nicht einmal kommen sehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[39124] = { id = 39124, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elchjagd", description = "Auf dem Hochberg leben Wildtiere, die man nirgendwo anders auf der Welt jagen kann. Sagt mir, {name}, ist Euch je zuvor ein Elch unter die Augen gekommen?\n\nDie umherziehenden Urhörner mögen wie sanfte Riesen aussehen, aber nur ein Narr würde ihre Stärke unterschätzen.\n\nSie müssten sogar für jemanden, der so erfahren ist, wie Ihr es seid, eine ziemliche Herausforderung darstellen.", sourceObjective = "Jagt Kieferfelsurhörner im Kieferfelsbecken.", completion = "Ihr habt die Urhörner des Hochbergs gejagt und sogar überlebt, um davon zu berichten. Das haben nicht viele vor Euch erreicht. Ich bin wirklich beeindruckt.", sourceObjectiveStatus = "unverified-source-field" }
quests[39125] = { id = 39125, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämonenvernichtung", description = "Wir müssen uns um diese Dämonen und die Verbreitung der Verderbnis kümmern. Macht ihre Pläne zunichte, indem Ihr ihre Generäle tötet.\n\nIch habe ein Geschenk für Euch. Dieses Horn hat mir Odyn selbst gegeben. Damit könnt Ihr alle Feinde niederringen, die Euch in die Quere kommen.\n\nDie Götter werden Euch ganz sicher wohlgesonnen sein, wenn es Euch gelingt, die Legion aufzuhalten.", sourceObjective = "Tötet Verdammnisrufer, Grinseschlund und Grinskett.", sourceObjectiveStatus = "unverified-source-field" }
quests[39127] = { id = 39127, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinter der Mauer", description = "Wir haben Nachricht davon erhalten, dass die Shado-Pan mit einem Gegenangriff auf die Tonlongsteppe begonnen haben. Es hört sich an, als wollten sie dem Ursprung der Yaungolinvasion auf den Grund gehen.\n\nDie Pandaren haben seit Tausenden von Jahren keine Streitkräfte in die Tonlongsteppe geführt. Die Shado-Pan sind stark und mutig, aber sie sind auch stolz und nur wenige. Sie werden die Hilfe von Helden wie Euch benötigen. Könnt Ihr durch das Tor von Winterblüte im Nordwesten reisen, um die Anführer der Shado-Pan zu finden und ihnen Eure Hilfe und Erfahrung anzubieten?", sourceObjective = "Sprecht mit Taran Zhu am Außenposten Longying in der Tonlongsteppe.", completion = "Willkommen in der Tonlongsteppe. Wenn Ihr schon darauf besteht, Euch in die dunkelsten Winkel Pandarias zu wagen, dann könnt Ihr Euch dabei auch wenigstens nützlich machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[39128] = { id = 39128, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tanaan Vignette" }
quests[39129] = { id = 39129, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Übellaunig", description = "<Nach dem Öffnen der Schriftrolle findet Ihr einen Plan, der aufzeigt, dass die Eiserne Horde große Fische in den Meeren Draenors manipulieren will, um die Schiffe der Allianz und der Horde anzugreifen. Unfassbarerweise scheint dieser Plan bei kleineren Haien schon funktioniert zu haben – zumindest teilweise.>", sourceObjective = "Bringt die Haigehirnwäschepläne zum Schiffsbauer Eurer Garnison.\n\nBereitgestellter Gegenstand:", sourceObjectiveStatus = "unverified-source-field" }
quests[39130] = { id = 39130, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Val'sharah - River: Vignette: Purging the River - TRACKING - twh" }
quests[39131] = { id = 39131, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Machtvolle Besitzstücke", description = "Echos tausender Welten hallen in Eurer Handfläche wider. Der wahre Wert liegt im Auge des Betrachters.", sourceObjective = "Sucht nach jenen, die Euch Einblick in die Herkunft des Splitters gewähren können.", sourceObjectiveStatus = "unverified-source-field" }
quests[39133] = { id = 39133, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Zeit zum Reden", description = "Dargrul hat seine Begleiter in den Kampf gegen uns geschickt.\n\nWir müssen diese Elementare vernichten, bevor ihr Zorn über Donnertotem hinwegfegt.", sourceObjective = "Zerstört 8 wütende Bernsteinsplitter.", completion = "Es ist sehr lange her, dass die Erde selbst sich so gegen uns erhoben hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[39134] = { id = 39134, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zornsplitter", description = "Der Unterkönig hat den Hammer von Khaz'goroth dazu benutzt, die Bergflanke in eine Waffe gegen uns zu verwandeln. Der Hammer ist ein Herstellungswerkzeug, keine Waffe zu seiner Belustigung!\n\nSein Kristalldiener, Zornsplitter, hetzt während wir sprechen die Elementare aus dem Berg auf meine Leute herab.\n\nWir müssen die Brücke gegen diesen Ansturm verteidigen.\n\nBegebt Euch in die Höhle, findet diesen Zornsplitter und schickt ihn in Einzelteilen zurück zu seinem Herrn.", sourceObjective = "Tötet Zornsplitter.", completion = "Ich vermute, das wird nicht der letzte Angriff von Dargrul gewesen sein. Er lernt immer noch die Macht des Hammers kennen wie ein Kind sein neues Spielzeug.", sourceObjectiveStatus = "unverified-source-field" }
quests[39136] = { id = 39136, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ungenutzt", description = "Ihr habt die Kanone aufgeladen. Jetzt solltet Ihr sie auch verwenden. Stellt Euch dem Kampf mit dem geisterhaften Magier Kiranys Abendwisper und vertreibt ihn aus Bradenbach.", sourceObjective = "Besiegt Kiranys Abendwisper am heimgesuchten Anwesen in Bradenbach.", sourceObjectiveStatus = "unverified-source-field" }
quests[39142] = { id = 39142, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein grausamer Feldversuch", description = "Jetzt, da der Blutstein genährt ist, hoffe ich, mithilfe seiner Macht den Willen von Dämonen zu beugen, die sich sonst nicht so leicht beherrschen lassen würden.\n\nDas ist natürlich alles graue Theorie. Ich habe die direkte Wirkung der Macht des Blutsteins auf einen Dämon noch nie gesehen. Da kommt Ihr ins Spiel.\n\nIch habe einige Wichtel besorgt, die sich als Versuchsobjekte eignen sollten. Wendet den Blutstein auf sie an und berichtet mir dann Eure Ergebnisse.", sourceObjective = "Wendet den Blutstein auf einen eingekerkerten Wichtel an.", completion = "Das Versuchsobjekt ist während der Prozedur verstorben? Das hätte ich nicht erwartet.\n\nDennoch habt Ihr Euren Teil der Abmachung erfüllt. Jetzt ist es wohl an der Zeit, dass ich das auch tue.", sourceObjectiveStatus = "unverified-source-field" }
quests[39149] = { id = 39149, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Dorf in Gefahr", description = "Noch ein Fremdling? Gerade ist so ein Kerl namens Jarod zu unserem Dorf aufgebrochen und hat behauptet, er könnte uns bei unserem Problem helfen.\n\nWenn auch Ihr gekommen seid, um zu helfen, solltet Ihr Euch am besten an den Bürgermeister wenden.\n\nIhr solltet jedoch wissen, dass dies keine gute Zeit ist und ihm der Finger am Abzug juckt.", sourceObjective = "Sprecht mit Bürgermeister Heathrow in Bradenbach.", completion = "Wir brauchen keine Hilfe. Und wir wollen nicht, dass Fremde durch unser Land schleichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[39152] = { id = 39152, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Felwrought Annihilator Looted" }
quests[39153] = { id = 39153, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schreckensflutdilemma", description = "Die Situation hat sich deutlich verschlechtert, {name}. Wir waren auf Graumähnes plötzlichen Angriff nicht eingestellt. Am Schreckensflutufer befindet sich nur noch eine kleine Einheit und dafür zahlen wir jetzt den Preis.\n\nDer Strand wimmelt jetzt nur so von Worgenspitzeln. Und wenn die Kanonen unsere Verteidigung aufbrechen, werden sie uns wohl überrennen. Wir haben zu wenig Leute, um sie anzugreifen und zurückzuschlagen, aber Ihr könnt das ändern.\n\nLöscht sie aus.", sourceObjective = "Tötet 10 Saboteure der Grauen Wacht bei Graumähnes Sturm.", completion = "Die Raben scheinen sich heute an Worgenfleisch satt fressen zu dürfen, {class}.\n\nGut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[39154] = { id = 39154, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Skold-Ashil", description = "{class}, dank Eures Eingreifens ist die Situation am Schreckensflutufer jetzt unter Kontrolle. Aber wir haben keine Zeit, uns auf unseren Lorbeeren auszuruhen. Wir müssen immer noch Sylvanas' Mission erfüllen.\n\nDie Dunklen Waldläuferinnen kontrollieren ihre Operationen in Skold-Ashil von dem Turm oberhalb der Flussgabelung herab. Sucht sie auf und bietet ihnen Eure Hilfe bei ihren Aufgaben an.", sourceObjective = "Trefft Euch mit den Dunklen Waldläuferinnen am Waldläufervorposten außerhalb von Skold-Ashil.", completion = "Seid Ihr etwa erstaunt, mich hier vorzufinden? Ich war selbst überrascht, dass meine Truppen noch nicht einmal in der Lage waren, auch nur eine kleine Bresche in die Verteidigung dieser verdammten Vrykulstadt zu schlagen!\n\nEs ist Zeit für neue Strategien, und Eure Ankunft könnte sich als sehr vorteilhaft erweisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[39155] = { id = 39155, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aszendentenriten", description = "Die Gravierungen scheinen einen Aszendentenritus darzustellen, mit dessen Hilfe die Schildmaiden die Kammer betreten können. Ich denke, das können wir zu unserem Vorteil nutzen.\n\nIhr müsst <der nächste Aszendent/die nächste Aszendentin> werden.\n\nBegebt Euch zum Tempel und vollzieht die Riten. Und wenn Ihr dazu über Leichenberge von Schildmaiden waten müsst, dann ist das eben so. \n\nSucht mich auf, wenn Ihr diese Aufgabe erfüllt habt, damit wir die Kammer für die Horde einnehmen können!", sourceObjective = "Versucht, den Segen an den vier Schreinen im Tempel von Skold-Ashil zu erlangen und dann mit der Statue zu kommunizieren.", completion = "Die Barriere ist ausgeschaltet und der Held kehrt zurück. Ich werde dafür sorgen, dass Ihr belobigt werdet.\n\nAber zunächst müssen wir diese Kammer einnehmen!", sourceObjectiveStatus = "unverified-source-field" }
quests[39156] = { id = 39156, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uther's Spirit Honored" }
