quests[39174] = { id = 39174, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Guiding Light Tutorialized" }
quests[39175] = { id = 39175, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Edelsteine der Apexis", description = "Hört zu, <Scheff/Scheffin>, ich weiß, Ihr seid Juwelenschleifer. Schon in Ordnung, versteh ich – auch mir gefällt Geld!\n\nHab gehört, wie einige der Vogelleute über eine neue Schleifmaschine geredet hab'n, die sie in Tanaan besorgt hatt'n. Würde ich mir selbst gern mal anseh'n, aber derzeit muss ich mich mit diesem Chaos an der Werft rumärgern.", sourceObjective = "Findet den Sonnenweisen Chakkis im Tanaandschungel.", completion = "Ja?", sourceObjectiveStatus = "unverified-source-field" }
quests[39176] = { id = 39176, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meisterschaft über Taladit", description = "Ihr – Ihr seid doch Edelsteinschleifer, oder? Das sieht man an Euren zuckenden Fingerknöcheln und der Konzentration in Euren Augen.\n\nIch suche hier in Tanaan nach etwas ganz Bestimmten. Wir konnten es in unseren Ausgrabungen in Arak nicht finden... doch die Apexis haben nicht nur in Arak gehaust.\n\nIch suche nach einem Apexiskonstrukt, das fürs Juwelenschleifen vorgesehen war. Haltet die Augen offen, Juwelenschleifer. Von solch einem Wunderwerk können wir beide profitieren.", sourceObjective = "Findet den Juwelenschleifer der Apexis.", completion = "<Das verwahrloste Konstrukt liegt zwischen Trümmern.>\n\n<Die Manipulatorarme deuten an, dass es für die Arbeit mit Edelsteinen geschaffen wurde.>", sourceObjectiveStatus = "unverified-source-field" }
quests[39177] = { id = 39177, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerstörtes Konstrukt", description = "<Es ist vernachlässigt, aber nicht kaputt. In erster Linie muss es erneut mit Energie versorgt werden.>\n\n<An der Rückseite der Maschine ist ein offener Einschub für... was auch immer die Apexis als Energiequelle verwendet haben.>", sourceObjective = "Repariert das Juwelenschleiferkonstrukt der Apexis, indem Ihr 1000 Apexiskristalle einsetzt.", completion = "Seid Ihr für die Rückkehr dieses Konstrukts verantwortlich, {name}? Es kam durch unser Lager getrampelt, als hätte es einen Auftrag. Brauchten drei Wächter, um es zu schnappen und zu überwältigen, aber vorerst scheint es zufrieden damit, hier zu bleiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[39178] = { id = 39178, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elch außer Rand und Band", description = "Ein durchgedrehter Elch, der das Becken terrorisiert, ist das Gesprächsthema in der Jagdhütte.\n\nIch selbst habe das Tier noch nie gesehen, aber man sagt, dass sein Geweih vor Magie leuchtet.\n\nAnders als die weniger fähigen Jäger, die ihm bisher nachgestellt haben, werdet Ihr erfolgreich sein. Bringt mir diese einzigartige Trophäe!", sourceObjective = "Beschafft das Geweih des verfluchten uralten Geistes Morashu.", progress = "Ich freue mich schon darauf, das Geweih eines uralten Geistes in der Jagdhütte an die Wand zu hängen!", completion = "Dieses Geweih wird an der Wand in der Jagdhütte einen ziemlich beeindruckenden Eindruck machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[39179] = { id = 39179, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutsteinbandit", description = "Mir wurde ein Gegenstand entwendet, der für mich persönlich von großem Wert ist. Ich kann meine Arbeit hier nicht fortsetzen, bis ich ihn wiederhabe.\n\nFür die meisten Augen sieht er wie ein gewöhnlicher Stein aus, doch er ist viel mehr. Er lebt und atmet!\n\nDie Naga in der Nähe haben sich alles auch nur annähernd Magische unter die Klauen gerissen, so auch meinen Stein. Zum Glück können sie seine Macht nicht erschließen.\n\nBringt mir meinen Stein zurück, dann erwäge ich Eure Bitte um Hilfe.", sourceObjective = "Holt Kiras Blutstein von Narashi Gallschuppe zurück.", progress = "Habt Ihr meinen Blutstein zurückbeschafft?", completion = "Ihr seid recht einfallsreich. Ich verstehe, warum Ritssyn Euch gerne Aufgaben überträgt.", sourceObjectiveStatus = "unverified-source-field" }
quests[39180] = { id = 39180, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Zangarmarschen!", description = "Die Hauptexpedition des Zirkels des Cenarius in der Scherbenwelt ist als Expedition des Cenarius bekannt. Sie fing als kleines Projekt unter der direkten Kontrolle des Zirkels an, aber inzwischen ist sie zu einer großen und ziemlich unabhängigen Organisation herangewachsen.\n\nDie Anführerin der Expedition, Ysiel Windsänger, hat uns gebeten, Freiwillige zur Zuflucht des Cenarius in den östlichen Zangarmarschen zu schicken. Nehmt den Pfad nach Westen und Ihr werdet direkt dorthin gelangen.", sourceObjective = "Sprecht mit Ysiel Windsänger in der Zuflucht des Cenarius in den Zangarmarschen.", completion = "Willkommen in der Zuflucht des Cenarius, {name}. Ich hoffe, Ihr könnt uns bei unserer Aufgabe behilflich sein. Wir haben viel Arbeit vor uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[39181] = { id = 39181, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Zangarmarschen!", description = "Die Hauptexpedition des Zirkels des Cenarius in der Scherbenwelt ist als Expedition des Cenarius bekannt. Sie fing als kleines Projekt unter der direkten Kontrolle des Zirkels an, aber inzwischen ist sie zu einer großen und ziemlich unabhängigen Organisation herangewachsen.\n\nDie Anführerin der Expedition, Ysiel Windsänger, hat uns gebeten, Freiwillige zur Zuflucht des Cenarius in den östlichen Zangarmarschen zu schicken. Nehmt den Pfad nach Westen und Ihr werdet direkt dorthin gelangen.", sourceObjective = "Sprecht mit Ysiel Windsänger in der Zuflucht des Cenarius in den Zangarmarschen.", completion = "Willkommen in der Zuflucht des Cenarius, {name}. Ich hoffe, Ihr könnt uns bei unserer Aufgabe behilflich sein. Wir haben viel Arbeit vor uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[39182] = { id = 39182, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Wälder von Terokkar!", description = "Wir haben den Kontakt mit den Druiden des Cenariusdickichts verloren.\n\nDer Kriegshäuptling hat befohlen, dass alle dienstfähigen Mitglieder der Horde sich sofort in die Wälder von Terokkar begeben und herausfinden, was passiert ist.\n\nZum Dickicht kommt Ihr, wenn Ihr nordwestlich der Zangarmarschen die Wäldern von Terokkar durchdringt.", sourceObjective = "Sprecht mit einem der Druiden beim Cenariusdickicht in den Wäldern von Terokkar.", completion = "Ich bin froh, dass die Steinbrecherfeste Euch geschickt hat. Die Druiden des Dickichts wurden ermordet! Nur ich und ein weiterer haben überlebt, und er ist geisteskrank.\n\nIch weiß nicht, was passiert ist, aber ich bin entschlossen, es herauszufinden. Was auch immer es war, es passierte schnell und fühlt sich unnatürlich an.\n\nWerdet Ihr mir helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[39183] = { id = 39183, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Immaculate Critical Strike Taladite" }
quests[39184] = { id = 39184, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Immaculate Haste Taladite" }
quests[39185] = { id = 39185, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Immaculate Mastery Taladite" }
quests[39186] = { id = 39186, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Immaculate Multistrike Taladite" }
quests[39187] = { id = 39187, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Immaculate Stamina Taladite" }
quests[39188] = { id = 39188, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Wälder von Terokkar!", description = "Wir haben den Kontakt mit den Druiden des Cenariusdickichts verloren.\n\nDer König hat befohlen, dass alle dienstfähigen Mitglieder der Allianz sich sofort in die Wälder von Terokkar begeben und herausfinden, was passiert ist.\n\nZum Dickicht kommt Ihr, wenn Ihr nordwestlich der Zangarmarschen die Wäldern von Terokkar durchdringt.", sourceObjective = "Sprecht mit einem der Druiden beim Cenariusdickicht in den Wäldern von Terokkar.", completion = "Ich bin froh, dass die Steinbrecherfeste Euch geschickt hat. Die Druiden des Dickichts wurden ermordet! Nur ich und ein weiterer haben überlebt, und er ist geisteskrank.\n\nIch weiß nicht, was passiert ist, aber ich bin entschlossen, es herauszufinden. Was auch immer es war, es passierte schnell und fühlt sich unnatürlich an.\n\nWerdet Ihr mir helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[39189] = { id = 39189, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Nagrand!", description = "Wir haben den Kontakt mit den Druiden des Cenariusdickichts verloren.\n\nDer Kriegshäuptling hat befohlen, dass alle dienstfähigen Mitglieder der Horde sich sofort in die Wälder von Terokkar begeben und herausfinden, was passiert ist.\n\nZum Dickicht kommt Ihr, wenn Ihr nordwestlich der Zangarmarschen die Wäldern von Terokkar durchdringt.", sourceObjective = "Sprecht mit einem der Druiden beim Cenariusdickicht in den Wäldern von Terokkar.", sourceObjectiveStatus = "unverified-source-field" }
quests[39191] = { id = 39191, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Vermächtnis des Eisbrechers", description = "Der mächtigste Krieger sollte die mächtigsten Waffen tragen. Vor langer Zeit führte der große König Magnar Eisbrecher Waffen, die aus einer Schuppe des größten Drachen des Landes gefertigt wurden. Er sollte hier sein, doch er ist es nicht. Stattdessen verweilt er voller Groll in seinem Grabmal.\n\nSein Sohn, Hruthnir, ist hier. Er wird Euch zu dem Grabmal führen. Rettet Magnar, wenn Ihr könnt, doch stellt sicher, dass Ihr nicht ohne seine Waffen zurückkehrt.", sourceObjective = "Kümmert Euch um Magnar Eisbrecher.", progress = "Ihr habt Euch großartig geschlagen. Ihr werdet diese Hallen mit vielen Triumphen schmücken.", completion = "Eine große Tat wurde heute vollbracht. Ich habe einen großen {class} gewonnen und Ihr ein mächtiges Artefakt.", sourceObjectiveStatus = "unverified-source-field" }
quests[39192] = { id = 39192, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schmiede von Odyn", description = "Diese Schmiede existiert schon länger als Euer Volk. Wir wissen also ein paar Dinge. Eure Waffe ist mächtig, aber Ihr braucht meine persönliche Schmiede, um sie zu verbessern.\n\nWir können am Artefakt arbeiten, um es zu verbessern, wenn Ihr genügend Erfahrung mit ihm angesammelt habt. Wollen wir es ausprobieren?", sourceObjective = "Verwendet die Schmiede von Odyn.", completion = "Das Potenzial Euer Waffe ist unermesslich! Ihr müsst Euch noch weiter mit ihr vertraut machen, bevor wir sie noch weiter verbessern können.", sourceObjectiveStatus = "unverified-source-field" }
quests[39193] = { id = 39193, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höllenfeuerangriff", description = "Wenn Ihr die Mauern dieser Zitadelle aufbrechen wollt, müsst Ihr Euch zunächst um Belagerungsausrüstung und die Truppen von Belagerungsmeisterin Mar'tak kümmern.\n\nIch hoffe, dass Ihr es heil und unversehrt in die Höllenfeuerzitadelle hinein schafft.", sourceObjective = "Wehrt den Höllenfeuerangriff bei der Höllenfeuerzitadelle ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[39195] = { id = 39195, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Edelsteine der Apexis", description = "Kommandant! Ich habe bemerkt, dass Ihr trotz des Krieges nicht die Juwelierskunst vernachlässigt. Ich finde das einfach bewundernswert.\n\nIch habe gehört, wie einige der Arakkoa über ein Juwelenschleifergerät gesprochen haben, das sie im Tanaandschungel vermuten. Sie haben diese Informationen von jemandem, den sie \"Chakkis\" nennen.\n\nIch dachte mir, das könnte Euch vielleicht interessieren.", sourceObjective = "Findet den Sonnenweisen Chakkis im Tanaandschungel.", completion = "Ja?", sourceObjectiveStatus = "unverified-source-field" }
quests[39196] = { id = 39196, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Nagrand!", description = "Der Kriegshäuptling ruft alle einsatzfähigen Champions der Horde auf, Garadar zu Hilfe zu eilen.\n\nDas Zuhause der Mag'har liegt im Süden, in Nagrand. Folgt der südlichen Straße aus den Marschen hinaus und wendet Euch an der ersten Weggabelung gen Osten, wo Ihr eine große Siedlung am See finden solltet.\n\nMeldet Euch dort bei Hauptmann Kroghan, und helft ihm, wo Ihr nur könnt. Garadar darf nicht fallen!", sourceObjective = "Sprecht mit Hauptmann Kroghan in Garadar in Nagrand.", completion = "<Auch wenn er sich Mühe gibt, es zu verheimlichen, macht sich Erleichterung auf Kroghans Gesicht breit.>\n\nEs wurde auch langsam Zeit, dass Ihr kommt! Sicher, Ihr seid keine Armee, {race}, aber hier ist ein jeder willkommen, der Kraft genug besitzt, eine Waffe zu führen oder einen Zauber zu wirken. Die Einwohner Garadars sind ein Teil der Horde und stolz, ihr Blut für deren Verteidigung vergießen zu dürfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[39197] = { id = 39197, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Nagrand!", description = "Der König hat Euch aufgefordert, ihn bei der Kurenaisiedlung in Telaar in Nagrand zu repräsentieren.\n\nWendet Euch dort an Aufseher Moi'bff Jill.", sourceObjective = "Sprecht mit Aufseher Moi'bff Jill in Telaar in Nagrand in der Scherbenwelt.", completion = "Eure Leute haben meinem guten Freund Ikuti einen großen Dienst erwiesen. Dafür seid Ihr hier in Telaar willkommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[39198] = { id = 39198, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Schergrat!", description = "Der Kriegshäuptling hat alle Champions aufgerufen, der Bedrohung durch die Oger am Schergrat ein Ende zu setzen. Geht nach Norden in die Berge zum orcischen Stützpunkt in der Donnerfeste und berichtet Gor'drek von unserer Bedrängnis. Jede Hilfe, die er uns zur Verfügung stellen kann, ist äußerst willkommen.", sourceObjective = "Reist zur Donnerfeste im Schergrat und sprecht mit Gor'drek.", completion = "Denjai braucht Hilfe? Ich würde ihm gerne ein paar Leute schicken, aber wir können uns selbst kaum halten. Wir haben hier oben unsere eigenen Probleme mit den Ogern.\n\nSobald ich kann, werde ich ihm alle Informationen, die wir über diesen Ogerstamm und seine Taktiken haben, zukommen lassen. Wenn er lang genug durchhält, können wir die widerlichen Kreaturen vielleicht von zwei Seiten aus angreifen.", sourceObjectiveStatus = "unverified-source-field" }
quests[39199] = { id = 39199, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Schergrat!", description = "Die Allianzstreitkräfte in Sylvanaar am Schergrat benötigen Unterstützung.\n\nDer König hat alle einsatzfähigen Mitglieder der Allianz aufgerufen, in die Berge an der nördlichen Grenze der Zangarmarschen zu reisen.", sourceObjective = "Sprecht mit Rina Mondquell in Sylvanaar im Schergrat.", completion = "Ah gut. Einsatzfähige Leute können wir gut gebrauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[39201] = { id = 39201, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Nethersturm!", description = "Die Goblins aus Area 52 im Nethersturm suchen einsatzfähige Champions, die bereit sind, ihnen Unterstützung bei ihren Vorhaben zu bieten.\n\nDer Kriegshäuptling meint, dass ihre Lage und Hilfe in dem Gebiet einen taktischen Vorteil vor den nahen Streitkräften von Kael'thas bieten würde.\n\nArea 52 könnt Ihr erreichen, indem Ihr der nordöstlichen Straße am Schergrat folgt, bis Ihr seht, wie die Welt in den Wirbelnden Nether zerbröckelt.", sourceObjective = "Meldet Euch bei Raketenchef Doppeldecker in Area 52.", completion = "He da. Braucht Ihr Arbeit? Ausgezeichnet!", sourceObjectiveStatus = "unverified-source-field" }
quests[39202] = { id = 39202, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Nethersturm!", description = "Die Goblins aus Area 52 im Nethersturm suchen einsatzfähige Champions, die bereit sind, ihnen Unterstützung bei ihren Vorhaben zu bieten.\n\nDer König meint, dass ihre Lage und Hilfe in dem Gebiet einen taktischen Vorteil vor den nahen Streitkräften von Kael'thas bieten würde.\n\nArea 52 könnt Ihr erreichen, indem Ihr der nordöstlichen Straße am Schergrat folgt, bis Ihr seht, wie die Welt im Wirbelnden Nether zerbröckelt.", sourceObjective = "Meldet Euch bei Raketenchef Doppeldecker in Area 52.", completion = "He da. Braucht Ihr Arbeit? Ausgezeichnet!", sourceObjectiveStatus = "unverified-source-field" }
quests[39203] = { id = 39203, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Drachenöde!", description = "Der Kriegshäuptling möchte die Truppen der Horde bei Agmars Hammer in der Drachenöde verstärken.\n\nDie Festung ist ein bedeutender Ausgangspunkt für einen Angriff auf Eiskrone und ist ausschlaggebend zur Eindämmung der chaotischen magischen Energien, die im Land verteilt sind.\n\nMeldet Euch bei Erzmagier Aethas Sonnenhäscher.", sourceObjective = "Sprecht mit dem Abbild des Erzmagiers Aethas Sonnenhäscher in Agmars Hammer.", completion = "Was hat denn so lange gedauert? Die Zeit wartet nur auf Aspekte, {race}.\n\nWir haben viel Arbeit zu tun – Ihr und ich.", sourceObjectiveStatus = "unverified-source-field" }
quests[39204] = { id = 39204, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Drachenöde!", description = "Es werden Freiwillige gesucht, um den Streitkräften des Silberbunds in der Drachenöde zu helfen, den chaotischen Energien entgegenzuwirken, die das Land in Stücke reißen könnten.\n\nAlle mit Begabung in der Bekämpfung von Drachen und Untoten sind äußerst willkommen.\n\nWer sich melden möchte, sollte sich an Erzmagierin Modera in Sternenruh in der Drachenöde wenden.", sourceObjective = "Sprecht mit dem Abbild von Erzmagierin Modera in Sternenruh.", completion = "Ich habe Euch erwartet, {class}. Wir haben viel Arbeit vor uns, Ihr und ich.", sourceObjectiveStatus = "unverified-source-field" }
quests[39206] = { id = 39206, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Befehl des Kriegshäuptlings: Grizzlyhügel!", description = "Ich habe von unserer Basis in den Grizzlyhügeln einen Hilferuf erhalten. Begebt Euch zu Eroberin Krenna.\n\nSie versucht, alle dortigen natürlichen Ressourcen für uns zu sichern. Hütet Euch nur vor ihr. Man sagt, dass sie selbst für einen Orc ziemlich aggressiv sein soll.\n\nIhr könnt sie erreichen, indem Ihr von der Drachenöde aus Richtung Osten reist.", sourceObjective = "Stellt Euch Eroberin Krenna vor. Sie befindet sich in Burg Siegeswall in den Grizzlyhügeln.", completion = "Wer seid Ihr?\n\nSagt mir, wieso ich Euch nicht an Ort und Stelle in zwei Teile spalten soll!", sourceObjectiveStatus = "unverified-source-field" }
quests[39207] = { id = 39207, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Grizzlyhügel!", description = "Während wir in Wintergarde uns darauf konzentrieren, standzuhalten und der Entwicklung der Dinge an der Pforte des Zorns entgegenzublicken, kämpfen sich Bataillone von so weit her wie Westfall durch das Dickicht der Grizzlyhügel mit all seinen unfreundlichen Bewohnern. Ihr Unternehmen ruht auf der Hoffnung, eine alternative Route zur Eiskrone zu finden.\n\nDer bei der Ammertannhütte stationierte Leutnant Dumont hat die Hilfe fähiger Bürger in Anspruch genommen, die gewillt sind, Leib und Leben in der unerforschten Wildnis aufs Spiel zu setzen. Werdet Ihr Euch dieser Herausforderung stellen?", sourceObjective = "Meldet Euch bei Leutnant Dumont an der Ammertannhütte in den westlichen Grizzlyhügeln.", completion = "Wilde Monster, diese Horde.\n\nSie werden für ihre Taten bezahlen. Zumindest darauf könnt Ihr Euch verlassen, {class}.\n\nNun ist es Zeit, dass Ihr Euch an die Arbeit macht.", sourceObjectiveStatus = "unverified-source-field" }
quests[39208] = { id = 39208, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zul'Drak", description = "Unsere Verbündeten bei den Todesrittern in Zul'Drak benötigen die Hilfe einiger Helden, um die Trolllande vor der Geißel zu bewahren.\n\nJene, die helfen wollen, sollten sich zu dem südwestlichen Lager, der Schwarzen Wacht, begeben und dort mit Stefan Vadu sprechen.", sourceObjective = "Meldet Euch bei Stefan Vadu in der Schwarzen Wacht in Zul'Drak.", completion = "<Stefan liest sich das Schreiben durch, zerknüllt es und wirf es ins Feuer.>\n\nNichts Neues. Der Argentumkreuzzug ist wieder einmal etwas zu langsam. Wir haben diesen Drakuru schon seit den Grizzlyhügeln verfolgt. Er ist zur Vernichtung bestimmt.", sourceObjectiveStatus = "unverified-source-field" }
quests[39209] = { id = 39209, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sholazarbecken", description = "Seit Hemet Nesingwary mit einer Expedition in die Tiefen des Sholazarbeckens aufgebrochen ist, hat niemand etwas von ihm oder dieser Expedition gehört.\n\nDer Pilot Monti Maulschuss wurde ausgesandt, um ihnen Vorräte zu liefern, doch auch er ist nie zurückgekehrt.\n\nEine Gruppe Freiwilliger muss aufbrechen, um die vermisste Expedition zu finden. Montis Flugmaschine wurde zuletzt im Wildwuchsmangal südlich der Sonnenstrahlsäule im Sholazarbecken gesichtet.", sourceObjective = "Sprecht mit Monti Maulschuss im Wildwuchsmangal des Sholazarbeckens.", sourceObjectiveStatus = "unverified-source-field" }
quests[39210] = { id = 39210, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das magische Königreich Dalaran", description = "Die Kirin Tor haben ihre Stadt hier nach Nordend verlegt.\n\nDalaran befindet sich nun nicht länger unter der schützenden Kuppel an den Ufern des Lordameresees. Nun schwebt die Stadt auf magische Art und Weise über dem Kristallsangwald.\n\nSie glauben, dass Ihr bereit seid, zu der Stadt zu reisen. Sucht im Kristallsangwald nach einem Teleportationskristall.\n\nWenn Ihr dort seid, so sprecht mit Erzmagierin Celindra.", sourceObjective = "Meldet Euch bei Erzmagierin Celindra am Violetten Tor in Dalaran.", completion = "Willkommen in Dalaran.", sourceObjectiveStatus = "unverified-source-field" }
quests[39212] = { id = 39212, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sholazarbecken", description = "Seit Hemet Nesingwary mit einer Expedition in die Tiefen des Sholazarbeckens aufgebrochen ist, hat niemand etwas von ihm oder dieser Expedition gehört.\n\nDer Pilot Monti Maulschuss wurde ausgesandt, um ihnen Vorräte zu liefern, doch auch er ist nie zurückgekehrt.\n\nErzmagier Pentarus in Dalaran wartet mit einer Flugmaschine darauf, dass er Euch zum letzten bekannten Standort von Monti Maulschuss bringen kann.", sourceObjective = "Sprecht mit Erzmagier Pentarus, wenn Ihr bereit seid, zum Sholazarbecken zu reisen. Sprecht mit Monti Maulschuss im Wildwuchsmangal, sobald Ihr im Sholazarbecken angekommen seid.", completion = "Ja, Hemet ist hier – er ist im Lager. Geht einfach nach Nordwesten in Richtung Fluss und Ihr werdet ihn schon bald sehen. Und bei der Liebe des Lichts, mein Junge, sorgt dafür, dass er jemanden schickt, um mich hier runterzuschneiden!", sourceObjectiveStatus = "unverified-source-field" }
quests[39214] = { id = 39214, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Auge von Odyn", description = "Es ist an der Zeit, den Krieg in Azeroth zu beginnen. Wir haben ein Werkzeug vorbereitet, mit dem Ihr Eure Krieger und Operationen von hier aus befehligen könnt. Es nennt sich das Auge von Odyn.\n\nFolgt mir bitte. Ich bringe Euch dorthin und stelle Euch jemanden zur Seite, der Euch darin unterweist.", sourceObjective = "Geht zum Auge von Odyn.", completion = "Es ist schon eine Weile her, dass ich mit den Lebenden gesprochen habe. Ich hoffe, dass Ihr meine Hilfe annehmt. Ich wurde bereits im Kampf getötet und kann dieser Notsituation mit mehr Gelassenheit begegnen als andere.", sourceObjectiveStatus = "unverified-source-field" }
quests[39216] = { id = 39216, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ready to forge Tracking Bit" }
quests[39217] = { id = 39217, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht verzagen, einfach graben!", description = "Nun, {name}, die gute Nachricht ist, dass unser Ausgrabungsteam unter uns auf eine Kammer gestoßen ist, die zu einem Gewölbe führt. Die schlechte Nachricht ist, dass auch die Horde dort war. Geht hinab und seht es Euch an.", sourceObjective = "Harrison Jones in Ashran möchte, dass Ihr Euch den tiefsten Bereich der Ausgrabungsstätte von Ashran anseht, der als 'Die Bresche' bezeichnet wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[39219] = { id = 39219, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Eiserne Bollwerk", description = "Die Belagerungsmeisterin in der Höllenfeuerzitadelle hat an einer ganz besonderen Maschine gearbeitet, die sie \"Eiserner Häscher\" nennt.\n\nMit ein bisschen Glück hat sie die Arbeit noch nicht beendet. Aber Ihr wisst ja, was passiert, wenn wir uns auf Glück verlassen...", sourceObjective = "Vernichtet den Eisernen Häscher bei der Höllenfeuerzitadelle.", sourceObjectiveStatus = "unverified-source-field" }
quests[39221] = { id = 39221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gruben des Mannoroth", description = "In der Höllenfeuerzitadelle versuchen sie, in den Gruben des Mannoroth einen Magnaron mit Teufelsmagie zu manipulieren.\n\nSeid auf der Hut, wenn Ihr Euch in diese teuflischen Gruben stürzt.", sourceObjective = "Vernichtet Kormrok in der Höllenfeuerzitadelle.", completion = "Ich frag' mich, ob der Magnaron in 'ne Grube gefallen is'. Kapiert?", sourceObjectiveStatus = "unverified-source-field" }
quests[39222] = { id = 39222, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hof des Blutes", description = "Es hat sich ein Rat von Orcklans zusammengefunden, der aufgelöst werden muss. Und zwar für alle Zeiten.\n\nIhr findet Gurtogg Siedeblut vom Blutenden Auge, Jubei'thos von der Brennenden Klinge und Dia Schattenflüsterer vom Schattenmondklan in den verfluchten Hallen der Höllenfeuerzitadelle.", sourceObjective = "Besiegt den Hohen Rat des Höllenfeuers in der Höllenfeuerzitadelle.", sourceObjectiveStatus = "unverified-source-field" }
quests[39223] = { id = 39223, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Totauges Vision", description = "Kilrogg Totauge hat seinen Klan auf einen finsteren Weg geführt, von dem aus es kein Zurück mehr gibt.\n\nDurch seine Adern fließt Dämonenblut und er erwartet den Moment seines – oder Eures – Todes in der Höllenfeuerzitadelle.", sourceObjective = "Vernichtet Kilrogg Totauge in der Höllenfeuerzitadelle.", sourceObjectiveStatus = "unverified-source-field" }
quests[39225] = { id = 39225, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Seelenschlund", description = "Nachdem Teron'gor in das Herz des Mausoleums in Auchindoun eingefallen war und Hunderte Draeneiseelen verschlungen hatte, verwandelte er sich in eine widerliche Monstrosität. \n\nTeron'gor hatte keine Ähnlichkeit mit einem Orc mehr und trieb fortan sein Unwesen unter dem Namen \"Blutschatten\".", sourceObjective = "Vernichtet Blutschatten in der Höllenfeuerzitadelle.", completion = "Ich hätt' nicht gedacht, dass dieses Monster mal ein Orc war, wenn Saurfang es mir nicht erzählt hätte.", sourceObjectiveStatus = "unverified-source-field" }
quests[39226] = { id = 39226, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Iskars Kralle", description = "Wir haben traurige Nachrichten über einen ehemaligen Vertrauten hereinbekommen. Der Arakkoa Iskar wollte um jeden Preis seine Flugfähigkeit zurückerlangen und hat sich Gul'dan angeschlossen, um seinen ursprünglich hochgeborenen Körper zurückzuerhalten.\n\nDer Preis dafür war aber die Verderbnis durch die Teufelsmagie. Und jetzt ist es an Euch, ihn davon zu erlösen.", sourceObjective = "Vernichtet Schattenfürst Iskar in der Höllenfeuerzitadelle.", sourceObjectiveStatus = "unverified-source-field" }
quests[39227] = { id = 39227, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amphitheater des Ewigen", description = "Der verräterische Exarch Socrethar wurde schon einmal mit Hilfe von Lady Liadrin und Exarch Maladaar besiegt.\n\nAber jetzt ist er zurückgekehrt. Sein bösartiger Geist befindet sich jetzt in einem seelengebundenen Konstrukt in der Höllenfeuerzitadelle. Er muss noch einmal ausgelöscht werden.", sourceObjective = "Vernichtet das seelengebundene Konstrukt in der Höllenfeuerzitadelle.", sourceObjectiveStatus = "unverified-source-field" }
quests[39228] = { id = 39228, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tempel der Tyrannei", description = "Tyrannin Velhari war einst eine viel versprechende Verteidigerin, aber aus Gründen, die nur sie selbst kennt, hat sie sich den Schatten zugewandt.\n\nLöscht diese Eredar der Finsternis aus.", sourceObjective = "Vernichtet Tyrannin Velhari in der Höllenfeuerzitadelle.", completion = "Und noch 'ne Anhängerin der Dunkelheit, die nie wieder das Licht sieht.", sourceObjectiveStatus = "unverified-source-field" }
quests[39229] = { id = 39229, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grommashs Folter", description = "Wir glauben, dass Grommash Gul'dans Angebot bis jetzt noch nicht angenommen und möglicherweise noch nicht einmal vom dargebotenen Blut getrunken hat.\n\nAber Gul'dan hat Teufelslord Zakuun auf Grommash angesetzt. Dieser Dämon ist Gul'dans bester Folterknecht.\n\nIch mache mir Sorgen um Grommash. Wenn sie ihn auf ihre Seite ziehen, sind wir alle in Gefahr.", sourceObjective = "Vernichtet Teufelslord Zakuun in der Höllenfeuerzitadelle.", sourceObjectiveStatus = "unverified-source-field" }
quests[39230] = { id = 39230, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bresche der Teufelsgeborenen", description = "Gul'dan hat ein Wesen namens Xhul'horac aus den Tiefen des Wirbelnden Nethers heraufbeschworen. Xhul'horac ist eines der mächtigsten Leerenphantome – einer parasitären Leerenspezies, die Löcher in die Strukturen der Realität reißt und alle Energie, die es dann vorfindet, aufnimmt und verschlingt.\n\nGul'dan hat Xhul'horac mit Teufelsenergie versorgt und für seine Zwecke manipuliert, um ihn ein Portal aufreißen zu lassen, durch das die Truppen der Brennenden Legion eindringen können.", sourceObjective = "Vernichtet Xhul'horac in der Höllenfeuerzitadelle.", sourceObjectiveStatus = "unverified-source-field" }
quests[39231] = { id = 39231, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Höhe des Zerstörers", description = "Wir dachten, dass wir Mannoroth ausgeschaltet hätten – zumindest für eine ganze Weile. Aber Gul'dan ist mächtiger, als wir angenommen haben.\n\nMannoroth ist fast schon wieder zurück in dieser Welt. Seine Knochen wurden im Innern der Zitadelle gesichtet und er muss vernichtet werden, bevor er zu voller Stärke gelangen kann.", sourceObjective = "Vernichtet Mannoroth in der Höllenfeuerzitadelle.", sourceObjectiveStatus = "unverified-source-field" }
quests[39232] = { id = 39232, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schwarze Tor", description = "Wir haben Gerüchte gehört, nach denen einer der stärksten Eredar diese Welt bald durch das Schwarze Tor betreten könnte.\n\nWenn das wahr ist, könnte es sich dabei um Archimonde den Entweiher handeln. Wenn wir ihn nicht gleich nach seiner Ankunft ausschalten, ist Draenor höchstwahrscheinlich verloren.", sourceObjective = "Vernichtet Archimonde in der Höllenfeuerzitadelle.", completion = "Ihr habt Draenor vor einem der stärkst'n Dämonen aller Zeiten gerettet, Kommandant. Über Euren Sieg werden sie in Liedern sing'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[39233] = { id = 39233, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer gräbt, der findet!", description = "Das seid Ihr ja endlich, {name}, und zwar gerade noch rechtzeitig. Ihr müsst Euch sofort in die Mine begeben und Euch anschauen, was wir dort entdeckt haben. Ihr müsst auf dem Weg vielleicht ein paar Allianztruppen ausschalten. Aber das sollte Euch die Sache wert sein.", sourceObjective = "Bellok Leuchtklinge in Ashran möchte, dass Ihr Euch in den tiefsten Teil der Ausgrabungsstätte in Ashran begebt, genannt 'Die Bresche'.", completion = "Gute Arbeit, {name}! Ihr seht ja selbst, was für ein Ärger die Allianz gemacht hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[39234] = { id = 39234, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höchste Dringlichkeit", description = "Meister Mathias Shaw vom SI:7 will Euch sehen. Er wartet auf Euch in den Tiefen unterhalb von Dalaran. Aber passt auf Euch auf. Es gibt Berichte über Personen, die in diesen Abwasserkanälen verschwunden sein sollen.", sourceObjective = "Sprecht mit Mathias Shaw in den Abwasserkanälen unterhalb von Dalaran.", sourceObjectiveStatus = "unverified-source-field" }
quests[39235] = { id = 39235, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buba" }
quests[39236] = { id = 39236, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An die Arbeit", description = "Jetzt, wo wir eine Werft haben, müssen wir uns an die Arbeit machen und Schiffe bauen! Solog ist schon zu den Trockendocks gegangen. Wollt Ihr ihn nicht dort aufsuchen? Er sagte, er habe einen Plan.", sourceObjective = "Trefft Euch mit Solog bei den Trockendocks.", completion = "Ich liebe den Geruch von frisch gefälltem Holz und Teer! Seid Ihr bereit, mit dem Bau zu beginnen?", sourceObjectiveStatus = "unverified-source-field" }
quests[39241] = { id = 39241, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schiffsbau", description = "Das Erste, was wir für den Bau von Schiffen benötigen, sind Baupläne. Dank Eurer Hilfe konnte ich ein paar der besten aus den Eisendocks an mich nehmen, bevor wir dort ausgebrochen sind.\n\nAber wir müssen sicherstellen, dass diese Pläne nicht erneut in die Hände der Eisernen Horde fallen. Ich möchte, dass Ihr Euch diese Baupläne einprägt und sie dann vernichtet. Sagt mir einfach Bescheid, wenn Ihr das erledigt habt.", sourceObjective = "Merkt Euch die Baupläne und vernichtet die Beweise.", progress = "Habt Ihr Euch die Pläne schon eingeprägt?", completion = "Ha! Aus Euch machen wir schon noch einen echten Seebären! Dann wollen wir mal unser erstes Schiff bauen!", sourceObjectiveStatus = "unverified-source-field" }
quests[39242] = { id = 39242, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schiff im Griff", description = "Ihr seid also entschlossen, Gul'dan anzugreifen? Dann braucht Ihr ein Transportschiff! Sprecht mich an, wenn Ihr bereit seid, mit dem Bau zu beginnen.", sourceObjective = "Sprecht mit Solog, um mit dem Bau eines Transportschiffes zu beginnen. Nach Fertigstellung sollte es Eurer Schiffssammlung hinzugefügt werden.", progress = "Schon mit dem Schiff angefangen?", completion = "So, fertig. Und sie ist eine echte Schönheit! Wenn Ihr eine Armee aufstellt, wird sie sie überall hinbringen.\n\nIch werde jetzt das Schiff für die erste Fahrt nach Tanaan vorbereiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[39243] = { id = 39243, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flottenkommandant", description = "Ihr habt wirklich ein Talent dafür, {name}. Vermutlich fließt Salzwasser durch Eure Adern. Jetzt ist es Zeit für unsere erste Marinemission und die Eroberung der Meere von Draenor!\n\nIhr braucht einen hohen Aussichtspunkt, um unsere Vorhaben auf See zu planen. Ich kenne eine gute Stelle am Ende des Pfades gleich hinter uns. Trefft mich am Eingang zur Werft, damit wir unsere erste Mission auf den Weg bringen können.", sourceObjective = "Findet Rolosh Wellenjäger, um eine Marinemission zu erfüllen.", completion = "Gute Arbeit, Kommandant! Ihr werdet eines Tages einen guten Kapitän abgeben!", sourceObjectiveStatus = "unverified-source-field" }
quests[39245] = { id = 39245, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Flotte vergrößern", description = "Ihr habt gute Arbeit da draußen geleistet, Kommandant. Wir benötigen allerdings noch mehr Erfahrung und Ressourcen, um diese Schiffswerft weiter aufzurüsten. Wenn wir unsere Ziele erreicht haben, können wir die Kapazität der Schiffswerft erhöhen!", sourceObjective = "Sammelt 1.000 Garnisonsressourcen, 1.000 Gold und schließt 15 Marinemissionen ab.", progress = "Schon Erfolg mit diesen neuen Marinemissionen gehabt?", completion = "Gute Arbeit! Ich mache mich sogleich daran, die Aufrüstung vorzunehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[39246] = { id = 39246, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorherrschaft auf hoher See", description = "Unsere Vorherrschaft auf hoher See besteht fort!\n\nWir benötigen allerdings noch mehr Erfahrung und Ressourcen, um diese Schiffswerft weiter aufzurüsten. Wenn wir unsere Ziele erreicht haben, können wir die Kapazität der Schiffswerft noch weiter erhöhen!", sourceObjective = "Sammelt 2.500 Garnisonsressourcen, 2.500 Gold und schließt 25 Marineschatzmissionen ab.", progress = "Habt Ihr die Ressourcen schon zusammen? Ich jedenfalls bin bereit, die Aufrüstung vorzunehmen!", completion = "Die Kontrolle über die Meere von Draenor ist in greifbarer Nähe!", sourceObjectiveStatus = "unverified-source-field" }
quests[39247] = { id = 39247, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Jagd", description = "Ihr führt diese Jagd an, {name}. Ein paar ausgewählte Illidari werden Euch begleiten, damit Varedis auch ganz sicher ausgeschaltet wird.\n\nDer Rest von uns bleibt zurück. Ein kleines Team hat bessere Chancen, sich der Festung unbemerkt zu nähern.\n\nWir treffen uns an Krasus' Landeplatz, sobald Ihr zum Aufbruch bereit seid.", sourceObjective = "Beschafft die Zwillingsklingen des Betrügers von Varedis Teufelsseele in Suramar.", completion = "Was ist mit den anderen? Sind sie...?\n\nIch verstehe. Sie haben ihr Leben nicht umsonst geopfert: Die Zwillingsklingen werden ganz sicher den Ausgang des Krieges entscheiden.", sourceObjectiveStatus = "unverified-source-field" }
quests[39250] = { id = 39250, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gruben des Mannoroth", description = "In der Höllenfeuerzitadelle versuchen sie, in den Gruben des Mannoroth einen Magnaron mit Teufelsmagie zu manipulieren.\n\nSeid auf der Hut, wenn Ihr in diese Teufelspfützen eintaucht.", sourceObjective = "Vernichtet Kormrok in der Höllenfeuerzitadelle.", completion = "Viel mehr von diesen teufelsverderbten Bestien können wir nicht standhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[39253] = { id = 39253, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Seelenschlund", description = "Nachdem Teron'gor in das Herz des Mausoleums in Auchindoun eingefallen war und Hunderte Draeneiseelen verschlungen hatte, verwandelte er sich in eine widerliche Monstrosität.\n\nTeron'gor hatte keine Ähnlichkeit mehr mit einem Orc und trieb fortan unter dem Namen \"Blutschatten\" sein Unwesen.", sourceObjective = "Vernichtet Blutschatten in der Höllenfeuerzitadelle.", completion = "Das war irgendeine Art von Monster, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[39256] = { id = 39256, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tempel der Tyrannei", description = "Tyrannin Velhari war einst eine viel versprechende Verteidigerin, aber aus Gründen, die nur sie selbst kennt, hat sie sich den Schatten zugewandt.\n\nLöscht diese Eredar der Finsternis aus.", sourceObjective = "Vernichtet Tyrannin Velhari in der Höllenfeuerzitadelle.", completion = "Wie kann ein Verteidiger so weit vom Pfad des Lichts abkommen?", sourceObjectiveStatus = "unverified-source-field" }
quests[39259] = { id = 39259, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Höhe des Zerstörers", description = "Wir dachten, dass wir Mannoroth ausgeschaltet hätten, zumindest für eine Weile. Aber Gul'dan ist mächtiger, als wir angenommen haben.\n\nMannoroth ist fast schon wieder zurück in dieser Welt. Seine Knochen wurden im Innern der Zitadelle gesichtet und er muss vernichtet werden, bevor er zu voller Stärke gelangen kann.", sourceObjective = "Vernichtet Mannoroth in der Höllenfeuerzitadelle.", completion = "Hoffen wir, dass Mannoroth diesmal länger außer Gefecht gesetzt bleibt.", sourceObjectiveStatus = "unverified-source-field" }
quests[39260] = { id = 39260, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schwarze Tor", description = "Wir haben Gerüchte gehört, nach denen einer der stärksten Eredar diese Welt bald durch das Schwarze Tor betreten könnte.\n\nWenn das wahr ist, könnte es sich dabei um Archimonde den Entweiher handeln. Wenn wir ihn nicht gleich nach seiner Ankunft ausschalten, ist Draenor höchstwahrscheinlich verloren.", sourceObjective = "Vernichtet Archimonde in der Höllenfeuerzitadelle.", completion = "Ihr habt Draenor vor einem der stärksten Dämonen aller Zeiten gerettet, Kommandant. Über Euren Sieg werden sie in Liedern singen.", sourceObjectiveStatus = "unverified-source-field" }
quests[39261] = { id = 39261, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf der Illidari", description = "{name}, Kayn möchte Euch sofort an Krasus' Landeplatz sprechen.\n\n<Kor'vas beugt sich zu Euch und flüstert eindringlich.>\n\nIhr müsst Euch beeilen. Die Legion hat ihre Augen überall.", sourceObjective = "Sprecht mit Kayn Sonnenzorn an Krasus' Landeplatz.", completion = "Wir haben viel zu tun und nur wenig Zeit dafür.", sourceObjectiveStatus = "unverified-source-field" }
quests[39262] = { id = 39262, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verleiht mir die Augen der Allsicht", description = "Jace Düsterweber schwört, er habe für einen kurzen Moment eine dämonische Präsenz hinter uns gespürt. Er hat mit einigen unserer Truppen die Höhle im Südosten untersucht.\n\nSie haben darin nichts gefunden, doch er ist sicher, dass etwas faul ist.\n\nWürdet Ihr ihm Eure Erfahrung und, wichtiger noch, Eure Geistersicht leihen?", sourceObjective = "Sprecht mit Jace Düsterweber und nutzt dann Eure Geistersicht, um die Höhle nach verborgenen Dämonen abzusuchen.", progress = "{name}, nutzt Eure Geistersicht, um die Höhle abzusuchen.\n\nWir müssen wissen, ob sich darin magisch getarnte Truppen der Legion verbergen.", completion = "Ich wusste, dass mich mein Gefühl nicht getrogen hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[39263] = { id = 39263, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausgrabungsstätte in Ashran" }
quests[39264] = { id = 39264, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bonus Objective: Ashran Excavation" }
quests[39265] = { id = 39265, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Tiny Viking Helmet" }
quests[39266] = { id = 39266, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Tiny Plated Helm" }
quests[39267] = { id = 39267, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Tiny Ninja Shroud" }
quests[39268] = { id = 39268, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Tiny Pirate Hat" }
quests[39271] = { id = 39271, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "First Mission Sent" }
quests[39272] = { id = 39272, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vergiftete Ernte", description = "Nachdem sie uns von unserem Ackerland vertrieben und unsere Feldfrüchte mit Insekten verseucht hatten, stellten die Drogbar widerliche Totems auf, um unsere Ernte noch weiter zu vergiften.\n\nIch kann nur hoffen, dass Ihr diese zerstört und wir danach in der Lage sein werden, unser Land mit Hilfe von Jales Wassermagie wieder zu heilen.\n\nDanke, dass Ihr gekommen seid, um uns zu helfen, {name}. Wir sind nur einfache Bauern und Fischer und haben nur sehr wenig Kampferfahrung.", sourceObjective = "Zerstört die Giftgötzen der Drogbar.", completion = "Ich danke Euch, {race}. Einige der Pflanzen sind noch lebendig. Ich glaube, mit harter Arbeit und ein wenig Wassermagie von Jale werden wir nicht die ganze Ernte verlieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[39273] = { id = 39273, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "First Mission Complete" }
quests[39274] = { id = 39274, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidigung der Flusslande" }
quests[39276] = { id = 39276, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seltsame Werkzeuge", description = "Wir sind auf bestem Wege, unser erstes Schiff zu bauen, aber ab hier bin ich nicht mehr von großem Nutzen. Ich habe keine Ahnung, wie man mit diesen Menschenwerkzeugen umgehen soll. Euer Schiffsbauer, Yanas Seestoß, wird sich von jetzt an um alles kümmern.\n\nIhr findet mich hier beim Trockendock, wenn Ihr noch etwas von mir braucht.", sourceObjective = "Sprecht mit Yanas Seestoß bei den Trockendocks.", completion = "Ihr habt also Interesse am Schiffsbau? Ich werde alles tun, was ich kann, um zu helfen, Kommandant.", sourceObjectiveStatus = "unverified-source-field" }
quests[39277] = { id = 39277, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Parfüm", description = "Das Käferspray, das Ihr Ormgul dem Befallenen abgenommen habt, könnte uns vielleicht einen Vorteil gegenüber den Drogbar und ihren Insekten verschaffen.\n\nSprüht die Drogbar mit ihrer eigenen Alchemie ein und Ihr werdet sehen, wie ihre Insekten sich gegen sie wenden.", sourceObjective = "Sprüht die Drogbar an den Weißwasserschnellen mit dem Käferspray ein.", completion = "Das hat ziemlich gut funktioniert. Ich werde etwas von diesem Käferspray behalten – es könnte in den bevorstehenden Kämpfen vielleicht noch einmal nützlich sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[39278] = { id = 39278, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das verschollene Manifest", description = "Der überwiegende Teil des wasserfesten Schreibens ist durch einen Code geschützt. In der Ecke seht Ihr eine hastig hingekritzelte Notiz für einen gewissen Herrn Matom: \"Wir wurden angegriffen... Wir konnten entkommen, aber das Schiff geht unter. Kommt und helft uns, bevor sie uns finden.\"\n\nDanach folgen ein paar Koordinaten zum gesunkenen Schiff. Herr Matom gehört definitiv zu den Leuten, bei denen man einen Gefallen gut haben sollte – und nicht anders herum.", sourceObjective = "Sucht nach Herrn Matoms verschollener Warenlieferung.", progress = "Was habt Ihr denn da?", completion = "Das... is' wichtig! Wo habt Ihr das gefund'n? Danach hab'n wir schon 'ne ganze Weile gesucht.\n\nHabt Ihr schon 'n Dock? Das is' SEHR interessant. Vielleicht werd'n wir noch richtige Freunde? Is' gar nich' so einfach, in Eure Festung Spione einzu... äh... Ich hab' nix gesagt.\n\nIch hab' 'ne Idee.", sourceObjectiveStatus = "unverified-source-field" }
quests[39279] = { id = 39279, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf Mardum" }
quests[39282] = { id = 39282, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Second Mission Complete" }
quests[39283] = { id = 39283, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oschi der Dämonenschlundfrenzys", progress = "Habt Ihr die Oschis, {name}?", completion = "Wow, was für ein Brocken.\n\nVielleicht ist das ja... Also, ich weiß gar nicht, was ich damit anstellen soll. Ist das wirklich ein Fisch?" }
quests[39285] = { id = 39285, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Second Mission Sent" }
quests[39286] = { id = 39286, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine schauerliche Aufgabe", description = "Passt auf, {name}, es geht um Folgendes: Einer unserer Agenten hat den Eingang zu der Portalwelt gefunden, in der Sargeras seinen persönlichen Teufelshund hält. Wir können ihn nicht direkt angreifen, aber er hat das Tier mit einer riesigen Menge Energie versehen.\nDas sind die guten Neuigkeiten.\n\nDie schlechten Neuigkeiten sind dafür ziemlich schauerlich. Er hat dieses Monster mit den Gehirnen unserer Verbündeten gefüttert, und etwas anderes frisst es gar nicht mehr. Es ist zwar grausam, aber an der Verheerten Küste befinden sich einige ihrer Leichen. Begebt Euch dorthin und bergt ein paar von ihnen.", sourceObjective = "Sammelt 5 abgetrennte Köpfe an der Verheerten Küste ein.", sourceObjectiveStatus = "unverified-source-field" }
quests[39287] = { id = 39287, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deathtalon" }
quests[39288] = { id = 39288, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Terrorfist" }
quests[39289] = { id = 39289, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Doomroller" }
quests[39290] = { id = 39290, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vengeance" }
quests[39299] = { id = 39299, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwarzmarkterei", description = "Das war 'n großer Gefallen heute, {name}. Boss Goya sagt, Ihr seid hier 'ne große Nummer und wir soll'n 'n Auge auf... also, wir sollen gute Kumpels werden. Sie hat 'n Abge... gesand... versandet... also 'n Del... i... get... also so 'ne Schwarzmarktperson zu Eurer Garnison geschickt.\n\nGeht 'mal hin und sagt hallo un' so. Und redet schön laut, wenn Ihr über Eure nächsten Pläne reden tut.", sourceObjective = "Sprecht mit Zhang Yeoh in Eurer Garnison.", completion = "Ich freue mich sehr, Eure Bekanntschaft machen zu dürfen, Kommandant. Wenn Ihr jemals die neuesten Wunder sehen möchtet, die Madame Goya Euch anbieten kann, dann zögert bitte nicht, mich anzusprechen. Sie lässt Euch dies hier als Zeichen des Dankes für Eure Mühen bei der Bergung des Manifestes zukommen.\n\nUnd denkt daran, dass Madame Goya nur persönliche Angebote entgegennimmt. Ihr müsst Euch zu ihr begeben, wenn Ihr Waren von ihr zu kaufen wünscht.", sourceObjectiveStatus = "unverified-source-field" }
quests[39303] = { id = 39303, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Third Mission Sent" }
quests[39304] = { id = 39304, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Third Mission Complete" }
quests[39305] = { id = 39305, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leeres Nest", description = "Ich habe die Eier, die Ihr geborgen habt, überprüft. Einige davon könnten vielleicht noch ausgebrütet werden.\n\nSie müssen in ein leeres Nest zurückgelegt werden, und mit ein bisschen Glück wird ein Adlerweibchen diese Eier annehmen und über sie wachen.\n\nGenau vor dem Eingang befindet sich ein Nest auf einem Felsvorsprung über der Höhle.\n\nSeid vorsichtig, {name}. Die Eier sind sehr zerbrechlich.", sourceObjective = "Legt die Adlereier vorsichtig in das leere Nest über dem Osteingang zur Felskriecherschlucht.", progress = "Wenn aus diesen Eiern noch etwas schlüpfen soll, dann müssen sie in ihr Nest zurückgebracht werden.", completion = "Dank Euch werden die großartigen Adler vom Hochberg weiterleben.\n\nAus einem der Eier, von dem ich dachte, es sei zu sehr beschädigt, um es zu retten, scheint etwas ausschlüpfen zu wollen...", sourceObjectiveStatus = "unverified-source-field" }
quests[39306] = { id = 39306, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms" }
quests[39307] = { id = 39307, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mechasuit" }
quests[39308] = { id = 39308, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bodyguard" }
quests[39309] = { id = 39309, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arcane Orb" }
quests[39310] = { id = 39310, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Artillery Strike" }
quests[39313] = { id = 39313, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Her mit der Verstärkung", description = "Seid gegrüßt, Kommandant! Jetzt, wo sich alle Kämpfe hier in Tanaan konzentrieren, können wir ein paar unserer Truppen von den nahe gelegenen Außenposten abziehen, um hier Fortschritte zu erzielen.\n\nSagt mir einfach, welche Verstärkungen ich anfordern soll, und ich werde sie im Handumdrehen hier antanzen lassen!", sourceObjective = "Sprecht mit Angar Stahlbalg und entscheidet, welche Verstärkungen nach Tanaan verlegt werden sollen.", completion = "Sehr gut! Ihr findet mich immer hier, falls Ihr Eure Meinung ändern solltet!", sourceObjectiveStatus = "unverified-source-field" }
quests[39315] = { id = 39315, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Her mit der Verstärkung", description = "Hey, Kommandant. Jetzt, wo alle Kämpfe hier in Tanaan stattfinden, sitzen ein paar unserer Truppen nutzlos in den nahe gelegenen Außenposten herum.\n\nSagt mir einfach Bescheid, wenn ich welche von denen anfordern soll!", sourceObjective = "Sprecht mit Knallix und entscheidet, welche Verstärkungen nach Tanaan verlegt werden sollen.", completion = "Jede Menge Artilleriemöglichkeiten zu Eurer freien Verfügung! Das ist der Traum eines jeden Kriegsherrn.\n\nUnd denkt daran: Ihr könnt jederzeit zu mir zurückkehren, wenn Ihr Eure Meinung ändern solltet!", sourceObjectiveStatus = "unverified-source-field" }
quests[39316] = { id = 39316, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tauren in der Falle", description = "Die Drogbar haben so viele von uns zusammengetrieben, wie sie konnten, und in eine Höhle in der Nähe gebracht.\n\nWenn Ihr schnell handelt, dann können sie, glaube ich, noch gerettet werden. Ich weiß nicht, was sie mit den Gefangenen vorhaben.\n\nMir graut es, wenn ich nur daran denke... an den tiefliegenden Orten regiert die Finsternis.", sourceObjective = "Befreit die gefangenen Tauren der Flussmähnen.", progress = "Sie haben viele meiner Brüder und Schwestern umgebracht, aber einige konnten die Flucht ergreifen. Andere wurden allerdings gefangen genommen.", completion = "Sie sind relativ unversehrt zurückgekommen. Ich danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[39317] = { id = 39317, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Belagerung der Scharrfurien" }
quests[39318] = { id = 39318, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wunden lecken", description = "Ich weiß, weshalb Mayla Euch schickte. Aber wie Ihr gesehen habt, sind die Drogbar nicht die einzige Gefahr am Hochberg.\n\nIch werde keine Truppen zur Unterstützung schicken, bis wir nicht mit den Lakaien der Großschwester der Scharrfurien fertiggeworden sind.\n\nWenn Ihr helfen wollt, sucht meinen Schamanen auf. Er sollte eigentlich die Feuer löschen, die in meinem Dorf wüten.\n\nEr wurde das letzte Mal auf dem Weg zu seinem Geisterhaus im Süden gesehen, kurz bevor die Aschenhexen uns angriffen.", sourceObjective = "Findet Windmeister Julan und helft, die Feuer auf dem Himmelshorn zu löschen.", progress = "Diese Harpyien sind einfach überall!", completion = "Julan ist tot? Er war ein guter Schamane und voller Leben. Nicht so morbide wie einige dieser Geistwandler.\n\nIch werde sein Lachen heute Nacht vermissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[39321] = { id = 39321, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Drei", description = "Als die Großschwester der Scharrfurien die Kontrolle über die Harpyien übernahm, übergab sie drei mächtigen und tödlichen Hexen den Befehl über die Zirkel unter ihr.\n\nDiese Hexen müssen sterben. Fühlt Ihr Euch dieser Aufgabe gewachsen?\n\nBegebt Euch in die Hexenlande hinter mir und findet diese bösartigen Kreaturen.\n\nWir werden Euch aus der Luft Deckung geben und Eurer Beute keine Chance zur Flucht in den Himmel lassen.\n\nWenn Ihr überleben solltet, findet Ihr uns oben auf dem Berg.", sourceObjective = "Tötet Ragi die Verhexerin, Agara Todesklage und Ugla die Hexe.", completion = "Gut gemacht. Wenden wir uns jetzt dem Kopf der Schlange zu.", sourceObjectiveStatus = "unverified-source-field" }
quests[39322] = { id = 39322, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hexenkönigin", description = "Die Zeit ist gekommen, die Großschwester der Scharrfurien, die Hexenkönigin, anzugreifen.\n\nIhr solltet wissen, dass man nicht durch Freundlichkeit zu Königin der Harpyien wird.\n\nDiese Kreatur hat zahllose Tauren, Harpyien und Kobolde getötet, gefoltert und ihnen alles Mögliche angetan, um ihre Position als Königin zu sichern.\n\nKommt, <Freund/Freundin>, lasst uns das beenden.", sourceObjective = "Tötet die Hexenkönigin, die Großschwester der Scharrfurien.", completion = "Ihr habt Euch Respekt und Ehre verdient, {name}. Ich ernenne Euch zum Himmelsfreund und gewähre Euch freien Durchlass durch unser Hoheitsgebiet.", sourceObjectiveStatus = "unverified-source-field" }
quests[39323] = { id = 39323, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moozys Verbleib", description = "Mein Sohn! Sie haben ihn mitgenommen! Meine Frau und ich haben uns aufgeteilt, um nach ihm zu suchen.\n\nBitte, geht und findet Moozy... ich werde schon klarkommen. Wenn Ihr Moozy findet, bringt ihn bitte flussaufwärts, zu meiner Frau.", sourceObjective = "Findet Moozy flussabwärts bei den Weißwasserschnellen.", completion = "<Moozy quietscht vor Freude über Eure Anwesenheit.>", sourceObjectiveStatus = "unverified-source-field" }
quests[39324] = { id = 39324, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durch das Portal", description = "Jetzt die guten Neuigkeiten: Ihr habt es fast geschafft. Ich bedaure, dass Ihr das tun musstet, aber Not macht eben erfinderisch. Seht Ihr das Portal dort unten? Dort lebt der Teufelshund. Geht dort hindurch und findet heraus, was dort vor sich geht.", sourceObjective = "Verwendet das dämonische Tor, um in die Portalwelt des Teufelshundes einzudringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[39325] = { id = 39325, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Mixer anwerfen", description = "Sieh an... Trankflecken auf dem Wappenrock und Kräuterreste auf den Stiefeln... Ihr seid ganz sicher in der Alchemie bewandert, genau wie ich!\n\nWir beide werden gut zusammenarbeiten. Ihr habt doch bestimmt nichts dagegen, neue Tricks zu lernen?\n\nIhr könnt meinen Alchemietisch verwenden. Er ist auf dem neuesten Stand der Technik. Ich habe ihn selbst angefertigt!", sourceObjective = "Deucus Valdera in Dalaran möchte, dass Ihr ein paar neue Tränke herstellt. Die Händlerin Patricia Egan im Alchemieladen kann Euch dabei helfen.", completion = "Habt Ihr die Tränke herstellen können? Das wäre der erste Schritt, um Vertrauen zwischen uns beiden aufzubauen.", sourceObjectiveStatus = "unverified-source-field" }
quests[39326] = { id = 39326, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verloren gegangene Lieferung", description = "Jetzt, wo wir uns ein bisschen kennengelernt haben, könntet Ihr mir vielleicht einen Gefallen erweisen.\n\nMeine Wochenlieferung an Vorräten ist verloren gegangen, als meine langjährige Kurierin... wie hieß sie doch gleich... nun, als sie über der Küste von Azsuna abgeschossen wurde. Jemand mit Euren kämpferischen Fähigkeiten müsste diese Sachen doch zurückholen können?", sourceObjective = "Alchemist Deucus Valdera in Dalaran möchte, dass Ihr seine verloren gegangenen Vorräte an der Küste von Azsuna ausfindig macht.", progress = "Ich hoffe doch sehr, dass Ihr meine Lieferung finden konntet? Wie sollen wir sonst Vertrauen aufbauen, wenn Ihr nicht alles macht, worum ich Euch bitte?", completion = "Ihr habt sie! Ich habe natürlich nie daran gezweifelt. Was können schon ein paar Dämonen oder Naga gegen jemanden ausrichten, der sich so entschlossen für sein Handwerk einsetzt wie Ihr?", sourceObjectiveStatus = "unverified-source-field" }
quests[39327] = { id = 39327, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dafür gibt es einen Schreiber", description = "Also schön! Ich gebe zu, dass selbst meine beachtliche Intelligenz nicht ausreicht, um den merkwürdigen Folianten, den Ihr entdeckt habt, zu übersetzen. Zweifellos ist er durch Wasserflecken unleserlich geworden.\n\nHört mal, einer von diesen dämlichen Schreibern einen Block weiter schuldet mir noch einen Gefallen. Diese Kleinarbeit ist genau sein Ding.", sourceObjective = "Bringt den runenbeschriebenen Folianten zu Professor Pallin in Dalaran.", progress = "Ich habe keine Zeit, um Folianten zu übersetzen! Dafür gibt es die niederen Berufe.", completion = "Scheinbar hat dieser Einfaltspinsel von einem Schreiber doch seinen Nutzen! Sehen wir mal, was er sich hat einfallen lassen...", sourceObjectiveStatus = "unverified-source-field" }
quests[39328] = { id = 39328, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uraltes Wissen", description = "Dieser Foliant enthält einen wahren Reichtum an uralten Vrykulrezepten! Ich könnte seit ewigen Zeiten der erste Alchemist sein, der eines davon verwendet! {name}, Ihr könnt Euch glücklich schätzen, <Zeuge/Zeugin> meiner Genialität zu werden!\n\nDas ist doch wirklich zu nett von dieser Svena, einfach zu sterben und uns dieses Buch zu hinterlassen, nicht wahr? Törichte Vrykul...", sourceObjective = "Seht Deucus Valdera dabei zu, wie er sich an einem der Vrykulrezepte versucht.", completion = "Mein armer Tisch!\n\nAlle Gerätschaften zum Mischen der neuen Tränke waren auf diesem Tisch. Ohne sie sind die neuen Rezepte wertlos!\n\nEs wird nicht einfach sein, Ersatz dafür zu finden, aber Euch traue ich es zu. Ich kann Euch auf die Orte hinweisen, an denen Ihr nach diesen Dingen suchen solltet.\n\nUnd jetzt eilt Euch!", sourceObjectiveStatus = "unverified-source-field" }
quests[39329] = { id = 39329, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der ausgebrannte Brenner", description = "Mir ist zu Ohren gekommen, dass jemand im Ingenieursladen einen Brenner verkauft, den wir möglicherweise verwenden könnten. Ihr könnt wahrscheinlich einen besseren Preis herausschlagen als ich!\n\nDer Laden ist auf der anderen Straßenseite. Ich markiere ihn auf Eurer Karte für Euch.", sourceObjective = "Kauft einen ausgebrannten Leyflammenbrenner von Hobart Wurfhammer und bringt ihn dann zu Deucus Valdera in Dalaran.", progress = "Nur gut, dass es andere Handwerker hier gibt, die so etwas herstellen. Ich selbst würde meine Zeit nicht damit verschwenden wollen.", completion = "Ah, dieser Brenner ist genau das, was wir für den Alchemietisch benötigen!\n\nNur einen kleinen Moment... Nein, nein, so geht das nicht!", sourceObjectiveStatus = "unverified-source-field" }
quests[39330] = { id = 39330, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leyjagd", description = "Dieser Leyflammenbrenner ist nutzlos! Genau deshalb traue ich Ingenieuren nicht...\n\nDer Brenner muss in Gebieten aufgeladen werden, die reich an Leyenergie sind, bevor wir damit an unseren neuen Alchemierezepten arbeiten können.\n\nGlücklicherweise verfügt Azsuna über genau solche Orte.", sourceObjective = "Reist zu den Hauptorten in Azsuna und verwendet den ausgebrannten Leyflammenbrenner zum Sammeln von Leyenergie.", completion = "Ihr habt also den Leyflammenbrenner mit neuer Leyenergie versehen? Lasst mal sehen.\n\n<Deucus untersucht den Leyflammenbrenner.>\n\nJa, das sollte funktionieren! Das ist ein wichtiger Schritt beim Wiederherstellen des Alchemietisches!", sourceObjectiveStatus = "unverified-source-field" }
quests[39331] = { id = 39331, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Auge Azsharas: Korken drauf", description = "Mir ist kürzlich etwas eingefallen, {name}. Die Naga sind dafür bekannt, alle möglichen Tränke zu horten, also haben sie vielleicht die Art Korken, die wir brauchen.\n\nMeiner Einschätzung nach ist die Gegend um das Auge Azsharas der beste Ort, um mit der Suche zu beginnen!\n\nVersucht, dort nicht zu viel Zeit mit den Angelegenheiten der Naga zu verschwenden, sondern konzentriert Euch auf die Suche nach Ersatzkorken.", sourceObjective = "Geht zum Auge Azsharas und beschafft die verbesserten Korken für Deucus Valdera in Dalaran.", progress = "Je schneller wir meine Utensilien zurückbekommen, desto schneller können wir uns an die eigentliche Arbeit machen.", completion = "Was ist das? Eine weitere Beute aus Euren Abenteuern? Lasst mal sehen...", sourceObjectiveStatus = "unverified-source-field" }
quests[39332] = { id = 39332, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Furbolgfeuerwasser", description = "Ja! Ich kenne diese Korken, die Ihr mir gebracht habt, {name}. Ich habe kürzlich ein paar davon von einem Furbolgstamm in Val'sharah erworben. Sie verwenden diese Korken zum Versiegeln des starken Feuerwassers, das sie selbst brennen.\n\nWir brauchen mehr von diesen Feuerwassertränken, denn diese Korken sind eine perfekte Ergänzung unseres Alchemietisches!", sourceObjective = "Besorgt ein paar Trinkschläuche Feuerwasser der Schwelhäute aus dem Furbolglager in Val'sharah. Bringt sie dann zu Deucus Valdera in Dalaran, damit er die Korken verwenden kann.", progress = "Habt Ihr noch mehr Feuerwassertränke gefunden? Gar nicht so einfach, sich selbst einen Schluck davon zu verwehren, was?", completion = "Diese Tränke haben die Korken, die wir für den Alchemietisch benötigen. Ein weiteres erfolgreiches Unterfangen!", sourceObjectiveStatus = "unverified-source-field" }
quests[39333] = { id = 39333, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine unpräzise Bürette", description = "Hier sind Eure Büretten. Solltet Ihr wieder einmal etwas brauchen, dann fragt mich einfach.\n\n<Fräulein Xiulan hält das Haar hoch und kichert weiter in sich hinein.>", sourceObjective = "Bringt die unkalibrierten Mallorybüretten zu Deucus in Dalaran.\n\nBereitgestellter Gegenstand:", completion = "Oh, ja, die sind gut. Sehr gut sogar. Leider müssen sie kalibriert werden, damit wir damit präzise Messungen vornehmen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[39334] = { id = 39334, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringen Scherben Glück?", description = "Hier ist Euer Fläschchen zurück... so gut wie neu. Ein guter Tausch gegen diese Tränke.\n\nUnd passt nächstes Mal bei zerbrechlichen Sachen etwas besser auf!", sourceObjective = "Bringt das reparierte zweikammerige Mischfläschchen zu Deucus Valdera in Dalaran.\n\nBereitgestellter Gegenstand:", completion = "Barm hat es also reparieren können? Wusste ich's doch, dass der Tauren das hinbekommt!\n\nDas ist eine schöne Ergänzung für meinen Alchemietisch.", sourceObjectiveStatus = "unverified-source-field" }
quests[39335] = { id = 39335, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neltharions Hort: Potentes Pulver", description = "Ich habe Gerüchte gehört, dass die Drogbar in alten Zeiten ein Pulver aus den Überresten von Drachenatem gewonnen hätten. Wenn es stimmt, dass Neltharions Hort irgendwo unter uns liegt, dann ist es gut möglich, dass man es dort finden kann.\n\nBegebt Euch dorthin und versucht, Ersatz für mein Pulver zu finden.", sourceObjective = "Beschafft Präzipitationspulver in Neltharions Hort und bringt es zu Deucus Valdera in Dalaran.", progress = "Was haben wir denn hier?", completion = "Ihr... Ihr habt es gefunden? Ich bin beeindruckt. Und das passiert nicht allzu häufig, müsst Ihr wissen.\n\nDann wollen wir uns doch mal anschauen, was genau Ihr da habt...", sourceObjectiveStatus = "unverified-source-field" }
quests[39336] = { id = 39336, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir brauchen mehr Pulver!", description = "Bei der Substanz, die Ihr mitgebracht habt, scheint es sich um Präzipitationspulver zu handeln, ein hoch instabiles Reagenz, das in den Rezepten der Vrykul Verwendung findet.\n\nMan sagt, dass eine Vrykulälteste namens Katterin ein ganzes Lager davon angelegt haben soll. Eine solch gefährliche Substanz gehört in unsere Hände, nicht in ihre!", sourceObjective = "Beschafft Katterins Alchemieset von Katterin der Blasenbedeckten in Sturmheim.", progress = "Hoffen wir, dass Ihr das Pulver findet, das wir benötigen...", completion = "Der Geist von dieser Svena ist schon wieder aufgetaucht? Sie scheint nicht darüber begeistert zu sein, dass wir diese Vrykulrezepte erlernen...\n\nGlücklicherweise war in dem Beutel, den Ihr beschafft habt, ausreichend Präzipitationspulver für unseren Alchemietisch. Ein weiterer Sieg für uns!", sourceObjectiveStatus = "unverified-source-field" }
quests[39337] = { id = 39337, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feiner Filter", description = "Als Nächstes benötige ich Ersatzfilter. Ihr habt Euch sicherlich schon gedacht, dass Alchemisten meines Kalibers beim Mischen von Tränken nur mit den besten Werkzeugen arbeiten.\n\nDie Elfen im Tempel von Elune in Val'sharah verwenden Shal'doreiseide für ihre Gewänder. Vielleicht erklären sie sich ja bereit, etwas davon für meine Filter abzutreten.", sourceObjective = "Sprecht mit einer Tempelpriesterin im Tempel von Elune und versucht, etwas Shal'doreiseide zu bekommen.", progress = "Auf der Truhe liegt ein Haufen zerrissener Shal'doreiseide.", completion = "Die Shal'doreiseide wurde in Streifen gerissen. Offensichtlich haben die Elfen sie als Bandagen für ihre gefallenen Krieger verwendet.", sourceObjectiveStatus = "unverified-source-field" }
quests[39338] = { id = 39338, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Filterersatz", description = "Was einst zerrissen war, ist nun wieder ganz. Ich hoffe, Ihr werdet die Shal'doreiseide sinnvoll nutzen.\n\nUnd jetzt ab mit Euch.", sourceObjective = "Bringt die ausgebesserte Shal'doreiseide zu Deucus Valdera in Dalaran.\n\nBereitgestellter Gegenstand:", completion = "Diese Shal'doreiseide wird einen ausgezeichneten Filter für den Alchemietisch abgeben. Gut, dass Ihr diese Nachtgeborene davon überzeugen konntet, uns zu helfen, {name}!", sourceObjectiveStatus = "unverified-source-field" }
